  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Letiště Glasgow', 'Letecký cíl ve Velké Británii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 55.87194, -4.43306, 'http://commons.wikimedia.org/wiki/Special:FilePath/GlasgowAirportFromAir.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/GlasgowAirportFromAir.jpg"}'::text[], 0, '{"en": {"name": "Glasgow Airport", "description": "International airport in Scotland, UK. An aviation sight in the United Kingdom — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Glasgow", "description": "Verkehrsflughafen der schottischen Metropole Glasgow. Ein Luftfahrt-Ziel in Großbritannien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Glasgow", "description": "Cel lotniczy w Wielkiej Brytanii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Glasgow International Airport", "description": "Internationale luchthaven in Renfrewshire, Verenigd Koninkrijk. Een luchtvaartdoel in het Verenigd Koninkrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto Internacional de Glasgow", "description": "Aeropuerto de Gran Bretaña. Un destino aeronáutico en el Reino Unido: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Glasgow", "description": "Aéroport situé à Glasgow, Écosse (Royaume-Uni). Un site aéronautique au Royaume-Uni — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Міжнародний аеропорт Глазго", "description": "Аеропорт в Шотландії. Авіаційна пам''ятка у Великій Британії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'St Mary''s Cathedral', 'Památka ve Velké Británii — kus historie přímo u trasy.', 55.8735, -4.275, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wfm%20st%20marys%20cathedral.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wfm%20st%20marys%20cathedral.jpg"}'::text[], 1, '{"en": {"name": "St Mary''s Cathedral", "description": "Church building in Glasgow, Scotland, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "St Mary''s Cathedral", "description": "Kirchengebäude in Glasgow, Schottland. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Najświętszej Maryi Panny w Glasgow", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Mariakathedraal", "description": "Kathedraal in Glasgow. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "St Mary''s Cathedral", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Sainte-Marie de Glasgow", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "St Mary''s Cathedral", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'St Andrew''s Cathedral', 'Památka ve Velké Británii — kus historie přímo u trasy.', 55.85567, -4.25284, 'http://commons.wikimedia.org/wiki/Special:FilePath/Front%20view%20of%20the%20St%20Andrew%27s%20Cathedral%2C%20Glasgow%2C%20Scotland%2016.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Front%20view%20of%20the%20St%20Andrew%27s%20Cathedral%2C%20Glasgow%2C%20Scotland%2016.jpg"}'::text[], 2, '{"en": {"name": "St Andrew''s Cathedral", "description": "Catholic cathedral in Glasgow, Scotland, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "St Andrew’s Cathedral", "description": "Kathedrale in Glasgow, Schottland. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Świętego Andrzeja w Glasgow", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "St Andrew''s Cathedral", "description": "Kathedraal in Glasgow, Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Andrés de Glasgow", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-André de Glasgow", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "St Andrew''s Cathedral", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Munga', 'Památka ve Velké Británii — kus historie přímo u trasy.', 55.8631, -4.2346, 'http://commons.wikimedia.org/wiki/Special:FilePath/2018%2007%2019%20Schottland%20%2833%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2018%2007%2019%20Schottland%20%2833%29.jpg"}'::text[], 3, '{"en": {"name": "Glasgow Cathedral", "description": "Church in Glasgow, Scotland, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "St. Mungo’s Cathedral", "description": "Kathedrale im Vereinigten Königreich. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Glasgow", "description": "Zabytkowy kościół w Szkocji. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Glasgow", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Glasgow", "description": "Iglesia en Glasgow, Escocia. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Mungo de Glasgow", "description": "Cathédrale à Glasgow. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Munga", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Antoninův val', 'Obranné opevnění ve Skotsku. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 55.967, -4.067, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bar%20Hill.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bar%20Hill.jpg"}'::text[], 4, '{"en": {"name": "Antonine Wall", "description": "Defensive fortification in Roman Britain. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Antoninuswall", "description": "Römische Grenzbefestigung. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Wał Antonina", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Muur van Antoninus", "description": "Romeinse limes in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Muro de Antonino", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "mur d''Antonin", "description": "Fortification romaine en Écosse. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Стіна Антонія", "description": "Фортифікаційна споруда Римської імперії в Північній Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Dumbarton Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 55.936, -4.5628, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dumbarton%20Castle%2020090607%20south%20entrance.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dumbarton%20Castle%2020090607%20south%20entrance.jpg"}'::text[], 5, '{"en": {"name": "Dumbarton Castle", "description": "Castle in West Dunbartonshire, Scotland, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Dumbarton Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Dumbarton Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Dumbarton Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Dumbarton", "description": "Fortaleza más antigua de Gran Bretaña. Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Dumbarton", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Дамбартон", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Loch Lomond', 'Jezero ve Skotsku. Vodní plocha ve Velké Británii — příjemný cíl vyjížďky s výhledy na hladinu.', 56.1482, -4.6515, 'http://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20loch%20lomond.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20loch%20lomond.JPG"}'::text[], 6, '{"en": {"name": "Loch Lomond", "description": "Freshwater lake in Scotland, UK. A body of water in the United Kingdom — a pleasant ride destination with waterside views."}, "de": {"name": "Loch Lomond", "description": "See in Schottland. Ein Gewässer in Großbritannien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Loch Lomond", "description": "Jezioro w Szkocji. Akwen w Wielkiej Brytanii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Loch Lomond", "description": "Meer in het Verenigd Koninkrijk. Een waterpartij in het Verenigd Koninkrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Loch Lomond", "description": "Lago del oeste de Escocia. Una masa de agua en el Reino Unido: un destino agradable con vistas al agua."}, "fr": {"name": "loch Lomond", "description": "Lac écossais. Un plan d''eau au Royaume-Uni — une belle destination avec vue sur l''eau."}, "uk": {"name": "Лох-Ломонд", "description": "Водойма у Великій Британії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
