    (v_route, 'Letiště Berlín-Schönefeld', 'Mezinárodní letiště jižně od Berlína. Letecký cíl v Německu — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 52.37861, 13.52056, 'http://commons.wikimedia.org/wiki/Special:FilePath/FLUGHAFEN%20SCHONEFELD%20BERLIN%20GERMANY%20JUNE%202013%20%289025967808%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/FLUGHAFEN%20SCHONEFELD%20BERLIN%20GERMANY%20JUNE%202013%20%289025967808%29.jpg"}'::text[], 0, '{"en": {"name": "Berlin Schönefeld Airport", "description": "Former international airport serving Berlin and Brandenburg, Germany. An aviation sight in Germany — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Berlin-Schönefeld", "description": "Ehemaliger Berliner Flughafen (heute Flughafen Berlin Brandenburg). Ein Luftfahrt-Ziel in Deutschland — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "port lotniczy Berlin-Schönefeld", "description": "Dawny port lotniczy w Niemczech, obsługujący Berlin oraz Brandenburgię. Cel lotniczy w Niemczech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Berlin-Schönefeld", "description": "Internationale luchthaven in Schönefeld, Duitsland. Een luchtvaartdoel in Duitsland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Berlín-Schönefeld", "description": "Aeropuerto de Alemania. Un destino aeronáutico en Alemania: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Berlin-Schönefeld", "description": "Aéroport desservant Berlin, Germany. Un site aéronautique en Allemagne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Берлін-Шенефельд", "description": "Авіаційна пам''ятка в Німеччині — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Müggelsee', 'Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 52.43333, 13.65, 'http://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BCggelsee%201.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BCggelsee%201.JPG"}'::text[], 1, '{"en": {"name": "Müggelsee", "description": "Lake in Köpenick, Berlin, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Müggelsee", "description": "Mit über 7,4 km² Wasserfläche der größte Berliner See, der sich im Bezirk Treptow-Köpenick befindet. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Müggelsee", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Müggelsee", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Müggelsee", "description": "Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Müggelsee", "description": "Lac de la région de Berlin, en Allemagne. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Müggelsee", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Katedrála svaté Hedviky Slezské', 'Kostel v Běrlíně, Německo. Památka v Německu — kus historie přímo u trasy.', 52.51583, 13.39472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Berlin%20Bebelplatz%20asv2018-05%20img1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Berlin%20Bebelplatz%20asv2018-05%20img1.jpg"}'::text[], 2, '{"en": {"name": "St. Hedwig''s Cathedral", "description": "Roman Catholic cathedral in Berlin, Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "St.-Hedwigs-Kathedrale", "description": "Römisch-katholische Kirche in Berlin. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Jadwigi w Berlinie", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Hedwigskathedraal", "description": "Kathedraal in Berlijn. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Santa Eduvigis de Berlín", "description": "Templo católico de Alemania. Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Sainte-Edwige de Berlin", "description": "Église allemande de Berlin. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Катедра Святої Ядвіґи", "description": "Катедральний храм у Берліні. Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Nová synagoga v Berlíně', 'Památka v Německu — kus historie přímo u trasy.', 52.52472, 13.39444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Neue%20Synagoge%2C%20Berlin-Mitte%2C%20160328%2C%20ako.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Neue%20Synagoge%2C%20Berlin-Mitte%2C%20160328%2C%20ako.jpg"}'::text[], 3, '{"en": {"name": "New Synagogue Berlin", "description": "Synagoge in Berlin. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Neue Synagoge", "description": "Synagoge in Berlin. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Nowa Synagoga w Berlinie", "description": "Synagoga (Berlin, Niemcy). Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Nieuwe Synagoge", "description": "Gebouw in Berlijn. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Nueva Sinagoga", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "Nouvelle synagogue de Berlin", "description": "Bâtiment de Spandauer Vorstadt, Berlin, Allemagne. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Nová synagoga v Berlíně", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Palác Bellevue', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 52.5175, 13.35333, 'http://commons.wikimedia.org/wiki/Special:FilePath/0%203494%20Berlin%20-%20Schloss%20Bellevue.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/0%203494%20Berlin%20-%20Schloss%20Bellevue.jpg"}'::text[], 4, '{"en": {"name": "Bellevue Palace", "description": "Official residence in Berlin for the President of the Federal Republic of Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Bellevue", "description": "Berliner Amtssitz des deutschen Bundespräsidenten. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Bellevue", "description": "Pałac w Berlinie, oficjalna rezydencja prezydenta Republiki Federalnej Niemiec. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Slot Bellevue", "description": "Bouwwerk in Berlijn, en officiële residentie van de President van Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Bellevue", "description": "Residencia oficial del Presidente de Alemania. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Bellevue", "description": "Résidence officielle du président fédéral d''Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Палац Бельв''ю", "description": "Офіційна урядова резиденція в Німеччині. Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Spandau Citadel', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 52.54096, 13.21259, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zitadelle%20B-Spandau%2007-2017%20img2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zitadelle%20B-Spandau%2007-2017%20img2.jpg"}'::text[], 5, '{"en": {"name": "Spandau Citadel", "description": "One of the best-preserved Renaissance military structures of Europe. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Zitadelle Spandau", "description": "Festung der Hochrenaissance in Berlin. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Cytadela Spandau", "description": "Jest jednym z najlepiej zachowanych renesansowych struktur wojskowych Europy. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Citadel van Spandau", "description": "Is een van de best bewaard gebleven renaissance militaire structuren van Europa. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Ciudadela de Spandau", "description": "Fortaleza en Berlín, Alemania. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "citadelle de Spandau", "description": "Une des structures militaires de la Renaissance les mieux conservées d''Europe. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Фортеця Шпандау", "description": "Історична пам''ятка Берліна. Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Großer Wannsee', 'Velký záliv řeky Havoly blízko berlínské městské části Steglitz-Zehlendorf. Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 52.4275, 13.17306, 'http://commons.wikimedia.org/wiki/Special:FilePath/Grosser%20Wannsee%20Berlin.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Grosser%20Wannsee%20Berlin.jpg"}'::text[], 6, '{"en": {"name": "Großer Wannsee", "description": "Lake near Berlin. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Großer Wannsee", "description": "Bucht der Havel in Berlin. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Großer Wannsee", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Großer Wannsee", "description": "Een meer vlakbij Berlin. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Wannsee", "description": "Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Großer Wannsee", "description": "Lac près de Berlin. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Großer Wannsee", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
