    (v_route, 'Letiště Birmingham', 'Mezinárodní letiště ve Velké Británii. Letecký cíl ve Velké Británii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 52.45389, -1.74806, 'http://commons.wikimedia.org/wiki/Special:FilePath/Birmingham%20Airport%2C%20England%2C%20Feb.%202008.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Birmingham%20Airport%2C%20England%2C%20Feb.%202008.jpg"}'::text[], 0, '{"en": {"name": "Birmingham Airport", "description": "Airport in Bickenhill, West Midlands, England. An aviation sight in the United Kingdom — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Birmingham Airport", "description": "Verkehrsflughafen der zweitgrößten britischen Stadt Birmingham. Ein Luftfahrt-Ziel in Großbritannien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Birmingham", "description": "Cel lotniczy w Wielkiej Brytanii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Internationale luchthaven van Birmingham", "description": "Bouwwerk in Birmingham‎. Een luchtvaartdoel in het Verenigd Koninkrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto Internacional de Birmingham-West Midlands", "description": "Aeropuerto de Gran Bretaña. Un destino aeronáutico en el Reino Unido: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Birmingham", "description": "Aéroport desservant Birmingham, au Royaume-Uni. Un site aéronautique au Royaume-Uni — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Бірмінгем", "description": "Авіаційна пам''ятка у Великій Британії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'St Philip''s Cathedral', 'Památka ve Velké Británii — kus historie přímo u trasy.', 52.4812, -1.89891, 'http://commons.wikimedia.org/wiki/Special:FilePath/Birmingham%20St%20Philip%27s%20Cathedral.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Birmingham%20St%20Philip%27s%20Cathedral.jpg"}'::text[], 1, '{"en": {"name": "St Philip''s Cathedral", "description": "Cathedral in Birmingham, West Midlands, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Birmingham", "description": "Kirchengebäude im Vereinigten Königreich. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Filipa w Birmingham", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Birmingham", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Felipe de Birmingham", "description": "Catedral en Birmingham. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Philippe de Birmingham", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "St Philip''s Cathedral", "description": "Церква у Великій Британії. Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
