    (v_route, 'Lichfieldská katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 52.6855, -1.8303, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lich%20Cath%20Face.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lich%20Cath%20Face.jpg"}'::text[], 3, '{"en": {"name": "Lichfield Cathedral", "description": "Cathedral in Lichfield, Staffordshire, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Lichfield", "description": "Kirchengebäude in Staffordshire, England. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Lichfield", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Lichfield", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Lichfield", "description": "Iglesia en Lichfield, Inglaterra. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Lichfield", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Lichfieldská katedrála", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Coventryská katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 52.40833, -1.50722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Coventry%20Cathedral%202018.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Coventry%20Cathedral%202018.jpg"}'::text[], 4, '{"en": {"name": "Coventry Cathedral", "description": "Cathedral in Coventry, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Coventry Cathedral", "description": "Kirchengebäude in England. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Coventry", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Coventry", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Coventry", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Michel de Coventry", "description": "Cathédrale britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Kenilworth Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 52.347, -1.59111, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kenilworth%20Castle%202016.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kenilworth%20Castle%202016.jpg"}'::text[], 5, '{"en": {"name": "Kenilworth Castle", "description": "Castle ruin in the town of Kenilworth, Warwickshire, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Kenilworth Castle", "description": "Burgruine in Kenilworth in Warwickshire, England, UK. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Kenilworth Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kenilworth Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "castillo de Kenilworth", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Kenilworth", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Кенілворт", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Warwick', 'Britský hrad. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 52.2796, -1.58561, 'http://commons.wikimedia.org/wiki/Special:FilePath/Warwick%20Castle%20May%202016.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Warwick%20Castle%20May%202016.jpg"}'::text[], 6, '{"en": {"name": "Warwick Castle", "description": "Medieval castle in Warwickshire, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Warwick Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Warwick", "description": "Średniowieczny zamek w środkowej Anglii. Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Warwick Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Warwick", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Warwick", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Ворик (замок)", "description": "Середньовічний замок. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb);
