    (v_route, 'Letiště Kolín/Bonn', 'Německé mezinárodní letiště. Letecký cíl v Německu — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 50.86592, 7.14274, 'http://commons.wikimedia.org/wiki/Special:FilePath/Glasdach%20Bahnhof%20K%C3%B6ln-Bonn%20Flughafen-7035.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Glasdach%20Bahnhof%20K%C3%B6ln-Bonn%20Flughafen-7035.jpg"}'::text[], 0, '{"en": {"name": "Cologne Bonn Airport", "description": "International airport of Germany''s fourth-largest city Cologne, and also serves Bonn, the former capital of West Germany. An aviation sight in Germany — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Köln/Bonn", "description": "Flughafen in Deutschland. Ein Luftfahrt-Ziel in Deutschland — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Kolonia/Bonn", "description": "Port lotniczy w Niemczech. Cel lotniczy w Niemczech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Keulen-Bonn", "description": "Internationale luchthaven in Troisdorf, Duitsland. Een luchtvaartdoel in Duitsland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Colonia/Bonn", "description": "Aeropuerto internacional localizado en la Reserva Natural de Wahner Heide, Alemania. Un destino aeronáutico en Alemania: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Cologne/Bonn", "description": "Aéroport desservant Cologne en Allemagne. Un site aéronautique en Allemagne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Кельн/Бонн", "description": "Авіаційна пам''ятка в Німеччині — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Bonnský chrám', 'Památka v Německu — kus historie přímo u trasy.', 50.73341, 7.09979, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bonner%20M%C3%BCnster.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bonner%20M%C3%BCnster.jpg"}'::text[], 1, '{"en": {"name": "Bonn Minster", "description": "Church. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Bonner Münster", "description": "Kirchengebäude in Bonn. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Bonn", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Munster van Bonn", "description": "Kerkgebouw in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Bonn", "description": "Bonn. Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Martin de Bonn", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bonnský chrám", "description": "Церква в Німеччині. Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Zámek Drachenburg', 'Zámek z 19. století v Německu. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 50.66867, 7.20634, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Schloss%20Drachenburg%20%28view%20from%20the%20northeast%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Schloss%20Drachenburg%20%28view%20from%20the%20northeast%29.jpg"}'::text[], 2, '{"en": {"name": "Schloss Drachenburg", "description": "19th century villa in Königswinter, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Drachenburg", "description": "Schloss in Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Schloss Drachenburg", "description": "Pałac w Königswinter, w Niemczech. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Schloss Drachenburg", "description": "Villa in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Schloss Drachenburg", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Drachenburg", "description": "Château construit sur le Drachenfels à Königswinter, Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Zámek Drachenburg", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Roonstrasse Synagogue', 'Památka v Německu — kus historie přímo u trasy.', 50.93212, 6.93668, 'http://commons.wikimedia.org/wiki/Special:FilePath/Synagoge%20Roonstra%C3%9Fe%2C%20K%C3%B6ln-7836.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Synagoge%20Roonstra%C3%9Fe%2C%20K%C3%B6ln-7836.jpg"}'::text[], 3, '{"en": {"name": "Roonstrasse Synagogue", "description": "Synagogue in Cologne. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Synagoge Köln", "description": "Synagoge in Köln, Stadtteil Neustadt-Süd. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Kolonii", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Synagoge van Keulen", "description": "Synagoge in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Sinagoga de Colonia", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Cologne", "description": "Synagogue allemande. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Roonstrasse Synagogue", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Basilica of the Holy Apostles', 'Památka v Německu — kus historie přímo u trasy.', 50.93652, 6.94523, 'http://commons.wikimedia.org/wiki/Special:FilePath/St.%20Aposteln%20K%C3%B6ln%20-%20Ostseite%20%284539%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St.%20Aposteln%20K%C3%B6ln%20-%20Ostseite%20%284539%29.jpg"}'::text[], 4, '{"en": {"name": "Basilica of the Holy Apostles", "description": "Church in Cologne-Altstadt-Nord, Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "St. Aposteln", "description": "Kirchengebäude in Köln-Altstadt-Nord, Deutschland. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół Świętych Apostołów w Kolonii", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Apostelenkerk", "description": "Keulen. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de los Santos Apóstoles", "description": "Iglesia en Colonia-Altstadt-Nord, Alemania. Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique des Saints-Apôtres de Cologne", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Basilica of the Holy Apostles", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Petra v Kolíně nad Rýnem', 'Katedrála v Kolíně nad Rýnem. Památka v Německu — kus historie přímo u trasy.', 50.94139, 6.95833, 'http://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6lner%20Dom%20von%20Osten.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6lner%20Dom%20von%20Osten.jpg"}'::text[], 5, '{"en": {"name": "Cologne Cathedral", "description": "Roman-Catholic cathedral in Cologne, Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Kölner Dom", "description": "Kirche in Köln, Deutschland. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Kolonii", "description": "Kościół (Kolonia, Niemcy; budowa: 1248–1880). Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Keulen", "description": "Kathedraal in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Colonia", "description": "Templo y monumento de Colonia, Alemania. Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Cologne", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кельнський собор", "description": "Католицький собор у Кельні, Німеччина. Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Benrath Palace', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 51.16103, 6.87057, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Benrath%20Jan2012.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Benrath%20Jan2012.jpg"}'::text[], 6, '{"en": {"name": "Benrath Palace", "description": "Baroque German Palace. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Benrath", "description": "Schloss in Düsseldorf, Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Benrath", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Schloss Benrath", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio Benrath", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Benrath", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Палац Бенрат", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb);
