    (v_route, 'Letiště Marseille Provence', 'Letiště ve Francii. Letecký cíl ve Francii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 43.43667, 5.215, 'http://commons.wikimedia.org/wiki/Special:FilePath/Marseille%20Provence%20Airport%202017%2005.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Marseille%20Provence%20Airport%202017%2005.jpg"}'::text[], 0, '{"en": {"name": "Marseille Provence Airport", "description": "International airport serving Marseille, France. An aviation sight in France — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Marseille Provence", "description": "Flughafen in Frankreich. Ein Luftfahrt-Ziel in Frankreich — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Marsylia", "description": "Cel lotniczy we Francji — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Marseille Provence", "description": "Vliegveld nabij Marseille, Frankrijk. Een luchtvaartdoel in Frankrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Marsella-Provenza", "description": "Un destino aeronáutico en Francia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport Marseille-Provence", "description": "Aéroport desservant Marseille et Aix-en-Provence (Bouches-du-Rhône, Provence-Alpes-Côte d''Azur, France). Un site aéronautique en France — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Марсель (аеропорт)", "description": "Авіаційна пам''ятка у Франції — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Étang de Berre', 'Vodní plocha ve Francii — příjemný cíl vyjížďky s výhledy na hladinu.', 43.44583, 5.11389, 'http://commons.wikimedia.org/wiki/Special:FilePath/%C3%89tang%20de%20Berre%20SPOT%201293.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%C3%89tang%20de%20Berre%20SPOT%201293.jpg"}'::text[], 1, '{"en": {"name": "Étang de Berre", "description": "French lagoon. A body of water in France — a pleasant ride destination with waterside views."}, "de": {"name": "Étang de Berre", "description": "Bucht in Frankreich. Ein Gewässer in Frankreich — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Étang de Berre", "description": "Akwen we Francji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Étang de Berre", "description": "Meer in Frankrijk. Een waterpartij in Frankrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Laguna de Berre", "description": "Una masa de agua en Francia: un destino agradable con vistas al agua."}, "fr": {"name": "étang de Berre", "description": "Grande lagune française, près de la Méditerranée. Un plan d''eau en France — une belle destination avec vue sur l''eau."}, "uk": {"name": "Етан-де-Берр", "description": "Водойма у Франції — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'D''If', 'Ostrovní pevnost poblíž Marseille. Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 43.27986, 5.32514, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20d%27If%20%40%20Baie%20de%20Marseille%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20d%27If%20%40%20Baie%20de%20Marseille%2001.jpg"}'::text[], 2, '{"en": {"name": "Château d''If", "description": "Fortification near Marseille, France. A castle in France — a historic stop worth the detour."}, "de": {"name": "Château d’If", "description": "Festung und ehemaliges Gefängnis auf einer Felseninsel vor der Küste von Marseille. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek d''If", "description": "Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Château d''If", "description": "Bouwwerk in Marseille. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de If", "description": "Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "château d''If", "description": "Forteresse française sur l''îlot d''If de l''archipel du Frioul au centre de la rade de Marseille. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "замок Іф", "description": "Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Notre-Dame de la Garde', 'Památka ve Francii — kus historie přímo u trasy.', 43.28395, 5.37123, 'http://commons.wikimedia.org/wiki/Special:FilePath/Notre%20Dame%20de%20la%20Garde%20%E5%AE%88%E8%AD%B7%E8%81%96%E6%AF%8D%E9%99%A2%20-%20panoramio%20%281%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Notre%20Dame%20de%20la%20Garde%20%E5%AE%88%E8%AD%B7%E8%81%96%E6%AF%8D%E9%99%A2%20-%20panoramio%20%281%29.jpg"}'::text[], 3, '{"en": {"name": "Notre-Dame de la Garde", "description": "Basilica located in Bouches-du-Rhône, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Notre-Dame de la Garde", "description": "Kirchengebäude in Marseille, Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Notre Dame de la Garde w Marsylii", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Notre-Dame-de-la-Garde", "description": "Bouwwerk in Marseille. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Notre-Dame de la Garde", "description": "Basílica situada en Marsella (Francia). Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Notre-Dame-de-la-Garde", "description": "Basilique située à Marseille dans les Bouches-du-Rhône, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Нотр-Дам-де-ля-Гард", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Marseille Cathedral', 'Památka ve Francii — kus historie přímo u trasy.', 43.2998, 5.36493, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20Sainte-Marie-Majeure%20de%20Marseille.%20Vue%20g%C3%A9n%C3%A9rale..JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20Sainte-Marie-Majeure%20de%20Marseille.%20Vue%20g%C3%A9n%C3%A9rale..JPG"}'::text[], 4, '{"en": {"name": "Marseille Cathedral", "description": "Cathedral located in Bouches-du-Rhône, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Kathedrale von Marseille", "description": "Bischofskirche in der französischen Stadt Marseille. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Archikatedra Sainte-Marie-Majeure w Marsylii", "description": "Świątynia katolicka. Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Cathédrale de la Major de Marseille", "description": "Bouwwerk in Marseille. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Marsella", "description": "Catedral situada en Bocas del Ródano, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Sainte-Marie-Majeure", "description": "Cathédrale située à Marseille dans les Bouches-du-Rhône, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Діви Марії в Марселі", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Národní park Calanques', 'Francouzský národní park. Přírodní zajímavost ve Francii — místo na protažení nohou uprostřed přírody.', 43.20944, 5.44917, 'http://commons.wikimedia.org/wiki/Special:FilePath/En-Vau%20calanque%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/En-Vau%20calanque%201.jpg"}'::text[], 5, '{"en": {"name": "Calanques National Park", "description": "National park in France. A natural sight in France — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Calanques", "description": "Eine Natursehenswürdigkeit in Frankreich — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Calanques", "description": "Atrakcja przyrodnicza we Francji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Calanques Nationaal Park", "description": "Nationaal park in Frankrijk. Een natuurbezienswaardigheid in Frankrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Calanques", "description": "Área protegida de Francia. Un paraje natural en Francia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national des Calanques", "description": "Parc national français à la fois terrestre et marin. Un site naturel en France — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Каланки", "description": "Природна пам''ятка у Франції — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Cosquerova jeskyně', 'Přírodní zajímavost ve Francii — místo na protažení nohou uprostřed přírody.', 43.20278, 5.44917, 'http://commons.wikimedia.org/wiki/Special:FilePath/Calanques%20de%20Marseille%2020120922%2036.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Calanques%20de%20Marseille%2020120922%2036.jpg"}'::text[], 6, '{"en": {"name": "Cosquer Cave", "description": "Cave in France. A natural sight in France — a spot to stretch your legs amid nature."}, "de": {"name": "Henry-Cosquer-Höhle", "description": "Höhle in Frankreich. Eine Natursehenswürdigkeit in Frankreich — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Jaskinia Cosquera", "description": "Atrakcja przyrodnicza we Francji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Grot van Cosquer", "description": "Een natuurbezienswaardigheid in Frankrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "Gruta Cosquer", "description": "Un paraje natural en Francia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "grotte Cosquer", "description": "Grotte ornée paléolithique des Bouches-du-Rhône, France. Un site naturel en France — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Коске", "description": "Природна пам''ятка у Франції — місце розім''яти ноги серед природи."}}'::jsonb);
