    (v_route, 'Boloňská katedrála', 'Církevní budova v Bologni, Itálie. Památka v Itálii — kus historie přímo u trasy.', 44.49565, 11.34292, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bologna%20-%20Portico%20della%20cattedrale%20di%20San%20Pietro%20-%202023-09-09%2018-09-17%20001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bologna%20-%20Portico%20della%20cattedrale%20di%20San%20Pietro%20-%202023-09-09%2018-09-17%20001.jpg"}'::text[], 1, '{"en": {"name": "Bologna Cathedral", "description": "Cathedral. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Kathedrale von Bologna", "description": "Kathedrale des Erzbistums Bologna, Italien. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Świętego Piotra w Bolonii", "description": "Świątynia katolicka. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Bologna Cathedral", "description": "Kathedraal in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Pedro en Bolonia", "description": "Catedral de Bolonia. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Bologne", "description": "Bâtiment historique de Bologne, en Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святого Петра (Болонья)", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'San Petronio Basilica', 'Památka v Itálii — kus historie přímo u trasy.', 44.49338, 11.34328, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bologna%20italy%20basilica%20di%20San%20Petronio.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bologna%20italy%20basilica%20di%20San%20Petronio.jpg"}'::text[], 2, '{"en": {"name": "San Petronio Basilica", "description": "Minor basilica. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Basilika San Petronio", "description": "Gebäude in Bologna, Italien. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Petroniusza w Bolonii", "description": "Kościół rzymskokatolicki. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Petroniusbasiliek", "description": "Bouwwerk in Bologna. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Petronio", "description": "Iglesia en Bolonia, Italia. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique San Petronio", "description": "Bâtiment historique de Bologne, en Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "San Petronio Basilica", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
