    (v_route, 'Sanctuary of the Madonna di San Luca', 'Památka v Itálii — kus historie přímo u trasy.', 44.47894, 11.29772, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bologna%20-%20Santuario%20della%20Madonna%20di%20San%20Luca.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bologna%20-%20Santuario%20della%20Madonna%20di%20San%20Luca.jpg"}'::text[], 5, '{"en": {"name": "Sanctuary of the Madonna di San Luca", "description": "Church building in Bologna, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Santuario della Madonna di San Luca", "description": "Kirchengebäude in Bologna, Italien. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Santuario della Madonna di San Luca", "description": "Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sanctuary of the Madonna di San Luca", "description": "Basiliek in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Santuario de Nuestra Señora de San Luca", "description": "Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "sanctuaire Madonna di San Luca", "description": "Bâtiment historique de Bologne, en Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Мадонна-ді-Сан-Лука", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála Nanebevzetí Panny Marie v Modeně', 'Katedrála v Itálii. Památka v Itálii — kus historie přímo u trasy.', 44.64644, 10.92525, 'http://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Modena%2020.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Modena%2020.JPG"}'::text[], 6, '{"en": {"name": "Modena Cathedral", "description": "Cathedral of Modena, Emilia-Romagna, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Kathedrale von Modena", "description": "Römisch-katholische Kathedrale im romanischen Baustil in der italienischen Stadt Modena. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Modenie", "description": "Świątynia katolicka. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Modena", "description": "Kathedraal in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Módena", "description": "Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Modène", "description": "Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Моденський кафедральний собор", "description": "Кафедральний собор у місті Модена, Італія. Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb);
