    (v_route, 'Letiště Řím Ciampino', 'Mezinárodní letiště v Římě. Letecký cíl v Itálii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 41.7995, 12.5914, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rom%20Flughafen%20Rom-Ciampino%202008%20by-RaBoe-01.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rom%20Flughafen%20Rom-Ciampino%202008%20by-RaBoe-01.jpg"}'::text[], 0, '{"en": {"name": "Rome Ciampino Airport", "description": "International airport serving Rome, Italy and the Vatican City. An aviation sight in Italy — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Rom-Ciampino", "description": "Flughafen in Italien. Ein Luftfahrt-Ziel in Italien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Rzym-Ciampino", "description": "Port lotniczy we Włoszech. Cel lotniczy we Włoszech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Rome Ciampino", "description": "Internationale luchthaven in Ciampino, Italië. Een luchtvaartdoel in Italië — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Roma-Ciampino", "description": "Aeropuerto italiano cercano a Roma. Un destino aeronáutico en Italia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Rome-Ciampino", "description": "Aéroport desservant Rome, en Italie. Un site aéronautique en Italie — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Аеропорт Рим-Чіампіно", "description": "Авіаційна пам''ятка в Італії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Albanské jezero', 'Jezero v Itálii, jižně od Říma. Vodní plocha v Itálii — příjemný cíl vyjížďky s výhledy na hladinu.', 41.7474, 12.669, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lago%20Albano%20%E2%80%A2%20Lake%20Albano%20%2846805866261%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lago%20Albano%20%E2%80%A2%20Lake%20Albano%20%2846805866261%29.jpg"}'::text[], 1, '{"en": {"name": "Lake Albano", "description": "Lake south of Rome, Italy. A body of water in Italy — a pleasant ride destination with waterside views."}, "de": {"name": "Albaner See", "description": "See im Süden Roms, Italien. Ein Gewässer in Italien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Albano", "description": "Akwen we Włoszech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Albano", "description": "Een waterpartij in Italië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Albano", "description": "Una masa de agua en Italia: un destino agradable con vistas al agua."}, "fr": {"name": "lac d''Albano", "description": "Lac italien. Un plan d''eau en Italie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Альбанське озеро", "description": "Водойма в Італії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Nemi', 'Vodní plocha v Itálii — příjemný cíl vyjížďky s výhledy na hladinu.', 41.71222, 12.7025, 'http://commons.wikimedia.org/wiki/Special:FilePath/Panoramica%20del%20Lago%20di%20Nemi.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Panoramica%20del%20Lago%20di%20Nemi.jpg"}'::text[], 2, '{"en": {"name": "Lake Nemi", "description": "Crater lake in Italy situated 25 km southeast of Rome. A body of water in Italy — a pleasant ride destination with waterside views."}, "de": {"name": "Nemisee", "description": "See in Mittelitalien. Ein Gewässer in Italien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Nemi", "description": "Jezioro we Włoszech. Akwen we Włoszech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Nemi", "description": "Een waterpartij in Italië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Nemi", "description": "Una masa de agua en Italia: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Nemi", "description": "Lac volcanique situé à 25 km au sud-est de Rome, Italie. Un plan d''eau en Italie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Немі", "description": "Водойма в Італії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Bazilika svatého Vavřince za hradbami', 'V Římě s hrobem sv. Vavřince na domnělým místem jeho umučení. Památka v Itálii — kus historie přímo u trasy.', 41.90253, 12.52055, 'http://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20of%20Saint%20Lawrence%20outside%20the%20Walls.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20of%20Saint%20Lawrence%20outside%20the%20Walls.jpg"}'::text[], 3, '{"en": {"name": "Basilica of Saint Lawrence Outside the Walls", "description": "One of the papal basilicas and Pilgrim Churches of Rome. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Sankt Laurentius vor den Mauern", "description": "Eine der Pilgerkirchen Roms. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Wawrzyńca za Murami", "description": "Bazylika mniejsza i kościół parafialny w Rzymie. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Laurens buiten de Muren", "description": "Kerkgebouw in Rome. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Lorenzo Extramuros", "description": "Basílica menor en Roma. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Laurent-hors-les-Murs", "description": "Église italienne de Rome. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Сан Лоренцо фуорі ле Мура", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Serviova hradba', 'Hrad či zámek v Itálii — historická zastávka, která stojí za odbočku.', 41.90167, 12.50167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ripa%20-%20le%20mura%20a%20via%20di%20sant%20anselmo%20051211-06.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ripa%20-%20le%20mura%20a%20via%20di%20sant%20anselmo%20051211-06.JPG"}'::text[], 4, '{"en": {"name": "Servian Wall", "description": "Defensive barrier around the ancient city of Rome. A castle in Italy — a historic stop worth the detour."}, "de": {"name": "Servianische Mauer", "description": "Römische Stadtmauer. Eine Burg bzw. ein Schloss in Italien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Mury serwiańskie", "description": "Zamek we Włoszech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Muur van Servius Tullius", "description": "Weermuur in Rome, Italië. Een kasteel in Italië — een historische stop die de omweg waard is."}, "es": {"name": "Murallas servianas", "description": "Un castillo en Italia: una parada histórica que merece el desvío."}, "fr": {"name": "muraille Servienne", "description": "Mur de défense de Rome. Un château en Italie — une halte historique qui vaut le détour."}, "uk": {"name": "Сервієва стіна", "description": "Замок в Італії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'San Pietro in Vincoli', 'Kostel v Římě. Památka v Itálii — kus historie přímo u trasy.', 41.89387, 12.49307, 'http://commons.wikimedia.org/wiki/Special:FilePath/San%20Pietro%20in%20Vincoli%20-%20Roma%2C%20facciata.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/San%20Pietro%20in%20Vincoli%20-%20Roma%2C%20facciata.jpg"}'::text[], 5, '{"en": {"name": "San Pietro in Vincoli", "description": "Church in Rome. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "San Pietro in Vincoli", "description": "Kirchengebäude in Rom. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Piotra w Okowach", "description": "Kościół w Rzymie. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "San Pietro in Vincoli", "description": "Kerkgebouw in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "San Pietro in Vincoli", "description": "Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Pierre-aux-Liens", "description": "Église italienne de Rome. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Сан П''єтро ін Вінколі", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Santa Maria in Aracoeli', 'Kostel v Římě. Památka v Itálii — kus historie přímo u trasy.', 41.89389, 12.48333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Santa%20Maria%20in%20Aracoeli%20%28Rome%29%20-%20Facade.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Santa%20Maria%20in%20Aracoeli%20%28Rome%29%20-%20Facade.jpg"}'::text[], 6, '{"en": {"name": "Santa Maria in Aracoeli", "description": "Church in Rome, on the Capitol Hill. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Santa Maria in Aracoeli", "description": "Kirchengebäude in Rom. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Matki Bożej Ołtarza Niebiańskiego", "description": "Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Santa Maria in Aracoeli", "description": "Kerkgebouw in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Santa María en Aracoeli", "description": "Iglesia católica en Roma, Italia, en la cima del Monte Capitolino. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Santa Maria in Aracoeli", "description": "Église italienne de Rome. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Санта Марія ін Арачелі", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb);
