    (v_route, 'Letiště Palma de Mallorca', 'Mezinárodní letiště ve Španělsku. Letecký cíl ve Španělsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 39.55168, 2.73881, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mallorca%20Palma%20airport%20asv2023-04%20img1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mallorca%20Palma%20airport%20asv2023-04%20img1.jpg"}'::text[], 0, '{"en": {"name": "Palma de Mallorca Airport", "description": "International airport in Palma, Spain. An aviation sight in Spain — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Palma de Mallorca", "description": "Flughafen in Spanien. Ein Luftfahrt-Ziel in Spanien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Palma de Mallorca", "description": "Port lotniczy na hiszpańskiej wyspie Majorka. Cel lotniczy w Hiszpanii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Palma de Mallorca", "description": "Vliegveld in Palma de Mallorca, Spanje. Een luchtvaartdoel in Spanje — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Palma de Mallorca", "description": "Aeropuerto en Palma de Mallorca, España. Un destino aeronáutico en España: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Palma de Majorque", "description": "Aéroport desservant Palma De Majorque en Espagne. Un site aéronautique en Espagne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Пальма-де-Мальорка", "description": "Авіаційна пам''ятка в Іспанії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Katedrála Panny Marie v Palma de Mallorca', 'Katedrála ve Španělsku. Památka ve Španělsku — kus historie přímo u trasy.', 39.5675, 2.64806, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kathedrale%20von%20Palma%20II.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kathedrale%20von%20Palma%20II.jpg"}'::text[], 1, '{"en": {"name": "Palma Cathedral", "description": "Cathedral and minor basilica in Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Kathedrale von Palma", "description": "Kathedrale auf Mallorca, Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra La Seu w Palma de Mallorca", "description": "Świątynia katolicka w Hiszpanii. Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Palma Cathedral", "description": "Kathedraal in Palma de Mallorca, Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Santa María de Palma de Mallorca", "description": "Templo católico de las Islas Baleares, (España). Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Palma de Majorque", "description": "Édifice religieux espagnol. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Пальмський собор", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Royal Palace of La Almudaina', 'Hrad či zámek ve Španělsku — historická zastávka, která stojí za odbočku.', 39.5675, 2.64722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Palma%20Mallorca%202008%2006.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Palma%20Mallorca%202008%2006.JPG"}'::text[], 2, '{"en": {"name": "Royal Palace of La Almudaina", "description": "Cultural property in Palma de Mallorca, Spain. A castle in Spain — a historic stop worth the detour."}, "de": {"name": "Royal Palace of La Almudaina", "description": "Burg in Spanien. Eine Burg bzw. ein Schloss in Spanien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Royal Palace of La Almudaina", "description": "Zamek w Hiszpanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Royal Palace of La Almudaina", "description": "Kasteel in Palma de Mallorca, Spanje. Een kasteel in Spanje — een historische stop die de omweg waard is."}, "es": {"name": "Palacio Real de la Almudaina", "description": "Bien de interés cultural y residencia estival de la familia real española. Un castillo en España: una parada histórica que merece el desvío."}, "fr": {"name": "palais royal de l''Almudaina", "description": "Une des résidences du roi d''Espagne situé à Palma. Un château en Espagne — une halte historique qui vaut le détour."}, "uk": {"name": "Royal Palace of La Almudaina", "description": "Пам''ятка культурної спадщини в Іспанії. Замок в Іспанії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bellver Castle', 'Hrad či zámek ve Španělsku — historická zastávka, která stojí za odbočku.', 39.56375, 2.61934, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Bellver.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Bellver.jpg"}'::text[], 3, '{"en": {"name": "Bellver Castle", "description": "Castle in Mallorca. A castle in Spain — a historic stop worth the detour."}, "de": {"name": "Castell de Bellver", "description": "Festung bei Palma de Mallorca, Spanien. Eine Burg bzw. ein Schloss in Spanien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Bellver Castle", "description": "Zamek w Hiszpanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Bellver Castle", "description": "Een kasteel in Spanje — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Bellver", "description": "Castillo en Mallorca. Un castillo en España: una parada histórica que merece el desvío."}, "fr": {"name": "château de Bellver", "description": "Château fort espagnol. Un château en Espagne — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Бельвер", "description": "Замок в Іспанії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Valldemossa Charterhouse', 'Památka ve Španělsku — kus historie přímo u trasy.', 39.70889, 2.62194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cartuja1.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cartuja1.JPG"}'::text[], 4, '{"en": {"name": "Valldemossa Charterhouse", "description": "Monastery in Mallorca. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Kartause von Valldemossa", "description": "Kloster in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Valldemossa Charterhouse", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kartuizerklooster van Valldemossa", "description": "Klooster in Valldemossa, Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Cartuja de Valldemosa", "description": "Monasterio desamortizado en las Islas Baleares, (España). Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "chartreuse de Valldemossa", "description": "Édifice religieux espagnol. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Вальдемоський монастир", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Castell d''Alaró', 'Hrad či zámek ve Španělsku — historická zastávka, která stojí za odbočku.', 39.73389, 2.79169, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castell%20d%27Alaro%201.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castell%20d%27Alaro%201.JPG"}'::text[], 5, '{"en": {"name": "Castell d''Alaró", "description": "Fortification. A castle in Spain — a historic stop worth the detour."}, "de": {"name": "Castell d’Alaró", "description": "Burg in Spanien. Eine Burg bzw. ein Schloss in Spanien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Castell d''Alaró", "description": "Zamek w Hiszpanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castell d''Alaró", "description": "Fortificatie in Spanje. Een kasteel in Spanje — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Alaró", "description": "Bien de interés cultural. Un castillo en España: una parada histórica que merece el desvío."}, "fr": {"name": "castel d’Alaró", "description": "Un château en Espagne — une halte historique qui vaut le détour."}, "uk": {"name": "Castell d''Alaró", "description": "Замок в Іспанії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Santuari de Lluc', 'Památka ve Španělsku — kus historie přímo u trasy.', 39.82292, 2.88444, 'http://commons.wikimedia.org/wiki/Special:FilePath/18-11-01-Mallorca-Lluc-DJI%200556-0558-HDR.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/18-11-01-Mallorca-Lluc-DJI%200556-0558-HDR.jpg"}'::text[], 6, '{"en": {"name": "Santuari de Lluc", "description": "Sanctuary in Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Santuari de Lluc", "description": "Kloster in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Santuari de Lluc", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Santuari de Lluc", "description": "Klooster in Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Santuario de Lluc", "description": "Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "sanctuaire de Lluc", "description": "Monastère en Espagne. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Santuari de Lluc", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb);
