    (v_route, 'Letiště Lublaň', 'Letecký cíl ve Slovinsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 46.22444, 14.45611, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ljubljana%20airport%202017.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ljubljana%20airport%202017.jpg"}'::text[], 0, '{"en": {"name": "Ljubljana Jože Pučnik Airport", "description": "International airport serving Ljubljana and the largest airport in Slovenia, located near Brnik, 24 km (15 mi) northwest of Ljubljana. An aviation sight in Slovenia — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Ljubljana", "description": "Flughafen in Slowenien. Ein Luftfahrt-Ziel in Slowenien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Lublana", "description": "Cel lotniczy w Słowenii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Ljubljana", "description": "Vliegveld in Slovenië. Een luchtvaartdoel in Slovenië — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Liubliana", "description": "Aeropuerto internacional de Liubliana, Eslovenia. Un destino aeronáutico en Eslovenia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport Jože Pučnik de Ljubljana", "description": "Aéroport desservant Ljubljana, Slovenia. Un site aéronautique en Slovénie — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Міжнародний аеропорт імені Йоже Пучніка", "description": "Аеропорт. Авіаційна пам''ятка у Словенії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Katedrála svatého Mikuláše', 'Kostel v Lublani. Památka ve Slovinsku — kus historie přímo u trasy.', 46.05071, 14.50824, 'http://commons.wikimedia.org/wiki/Special:FilePath/StNicholas-Ljubljana.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/StNicholas-Ljubljana.JPG"}'::text[], 1, '{"en": {"name": "Ljubljana Cathedral", "description": "Cathedral. A heritage sight in Slovenia — a piece of history right on your route."}, "de": {"name": "Dom St. Nikolaus (Ljubljana)", "description": "Kathedrale in Slowenien. Ein Denkmal in Slowenien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Świętego Mikołaja w Lublanie", "description": "Świątynia katolicka. Zabytek w Słowenii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Nicolaaskathedraal", "description": "Ljubljana. Een monument in Slovenië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Nicolás", "description": "Catedral en Liubliana, Eslovenia. Un monumento en Eslovenia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Nicolas de Ljubljana", "description": "Un monument en Slovénie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор святого Миколая (Любляна)", "description": "Пам''ятка у Словенії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Lublaňský hrad', 'Hrad ve Slovinsku. Hrad či zámek ve Slovinsku — historická zastávka, která stojí za odbočku.', 46.04871, 14.50863, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ljubljanski%20grad%20in%20Grajski%20gri%C4%8D.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ljubljanski%20grad%20in%20Grajski%20gri%C4%8D.jpg"}'::text[], 2, '{"en": {"name": "Ljubljana Castle", "description": "Castle in Slovenia. A castle in Slovenia — a historic stop worth the detour."}, "de": {"name": "Laibacher Schloss", "description": "Burg in Slowenien. Eine Burg bzw. ein Schloss in Slowenien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Lublanie", "description": "Zamek w Słowenii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Ljubljanski Grad", "description": "Kasteel in Slovenië. Een kasteel in Slovenië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Liubliana", "description": "Castillo de Liubliana. Un castillo en Eslovenia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Ljubljana", "description": "Un château en Slovénie — une halte historique qui vaut le détour."}, "uk": {"name": "Люблянський замок", "description": "Замок у Словенії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bogenšperk Castle', 'Hrad či zámek ve Slovinsku — historická zastávka, která stojí za odbočku.', 46.0236, 14.85824, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bogen%C5%A1perk%20vhodna%20stran.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bogen%C5%A1perk%20vhodna%20stran.JPG"}'::text[], 3, '{"en": {"name": "Bogenšperk Castle", "description": "Castle in central Slovenia. A castle in Slovenia — a historic stop worth the detour."}, "de": {"name": "Burg Wagensberg", "description": "Burg in Slowenien. Eine Burg bzw. ein Schloss in Slowenien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Bogenšperk", "description": "Zamek w Słowenii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Bogenšperk Castle", "description": "Kasteel in Slovenië. Een kasteel in Slovenië — een historische stop die de omweg waard is."}, "es": {"name": "Bogenšperk Castle", "description": "Un castillo en Eslovenia: una parada histórica que merece el desvío."}, "fr": {"name": "Bogenšperk Castle", "description": "Un château en Slovénie — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Богеншперк", "description": "Замок у Словенії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Potok Cave', 'Přírodní zajímavost ve Slovinsku — místo na protažení nohou uprostřed přírody.', 46.44939, 14.66906, 'http://commons.wikimedia.org/wiki/Special:FilePath/Potok%20Cave%20-%20Poto%C4%8Dka%20zijalka%20%28Slovenia%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Potok%20Cave%20-%20Poto%C4%8Dka%20zijalka%20%28Slovenia%29.JPG"}'::text[], 4, '{"en": {"name": "Potok Cave", "description": "Cave in Slovenia. A natural sight in Slovenia — a spot to stretch your legs amid nature."}, "de": {"name": "Potočka zijavka", "description": "Archäologische Stätte in Slowenien. Eine Natursehenswürdigkeit in Slowenien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Potočka", "description": "Jaskinia w Słowenii. Atrakcja przyrodnicza w Słowenii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Potok Cave", "description": "Archeologische vindplaats in Slovenië. Een natuurbezienswaardigheid in Slovenië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Potok Cave", "description": "Un paraje natural en Eslovenia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Potok Cave", "description": "Un site naturel en Slovénie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Потоцька печера", "description": "Природна пам''ятка у Словенії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Bledský hrad', 'Hrad ve Slovinsku. Hrad či zámek ve Slovinsku — historická zastávka, která stojí za odbočku.', 46.36972, 14.10056, 'http://commons.wikimedia.org/wiki/Special:FilePath/4260%20Bled%2C%20Slovenia%20-%20panoramio.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/4260%20Bled%2C%20Slovenia%20-%20panoramio.jpg"}'::text[], 5, '{"en": {"name": "Bled Castle", "description": "Medieval castle in Bled, Slovenia. A castle in Slovenia — a historic stop worth the detour."}, "de": {"name": "Burg Bled", "description": "Burg in Slowenien. Eine Burg bzw. ein Schloss in Slowenien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Bled", "description": "Zamek w Słowenii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Bled", "description": "Kasteel in Slovenië. Een kasteel in Slovenië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Bled", "description": "Un castillo en Eslovenia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Bled", "description": "Château médiéval construit sur une falaise surplombant Bled (Slovénie). Un château en Slovénie — une halte historique qui vaut le détour."}, "uk": {"name": "Bledský hrad", "description": "Замок у Словенії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bledské jezero', 'Jezero ve Slovinsku. Vodní plocha ve Slovinsku — příjemný cíl vyjížďky s výhledy na hladinu.', 46.36444, 14.09472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Bled%20%28view%20from%20the%20southwest%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Bled%20%28view%20from%20the%20southwest%29.jpg"}'::text[], 6, '{"en": {"name": "Lake Bled", "description": "Lake in Slovenia. A body of water in Slovenia — a pleasant ride destination with waterside views."}, "de": {"name": "Bleder See", "description": "See in Slowenien. Ein Gewässer in Slowenien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezioro Bledzkie", "description": "Jezioro polodowcowe w Słowenii. Akwen w Słowenii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Bled", "description": "Meer in Slovenië. Een waterpartij in Slovenië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Bled", "description": "Una masa de agua en Eslovenia: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Bled", "description": "Lac d''origine glaciaire en Slovénie. Un plan d''eau en Slovénie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Бледське озеро", "description": "Озеро в Альпах у північно-західній Словенії. Водойма у Словенії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
