    (v_route, 'Circuit de Spa-Francorchamps', 'Závodní okruh pro automobilový sport ve stejnojmenném městě. Motoristický cíl v Belgii — rychlost, okruhy a legendy motorismu na dosah.', 50.43722, 5.97139, 'http://commons.wikimedia.org/wiki/Special:FilePath/2022%204%20Hours%20of%20Spa-Francorchamps%20-%20Circuit.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2022%204%20Hours%20of%20Spa-Francorchamps%20-%20Circuit.jpg"}'::text[], 0, '{"en": {"name": "Spa-Francochamps Circuit", "description": "Motorsport race track near Spa, Belgium. A motorsport sight in Belgium — speed, circuits and motoring legends within reach."}, "de": {"name": "Circuit de Spa-Francorchamps", "description": "Motorsport-Rennstrecke in Belgien. Ein Motorsport-Ziel in Belgien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Circuit de Spa-Francorchamps", "description": "Tor wyścigowy w Belgii. Cel motoryzacyjny w Belgii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Circuit Spa-Francorchamps", "description": "Belgisch racecircuit. Een autosportdoel in België — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Circuito de Spa-Francorchamps", "description": "Autódromo belga. Un destino del motor en Bélgica: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit de Spa-Francorchamps", "description": "Circuit automobile belge. Un site du sport mécanique en Belgique — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Спа-Франкоршам", "description": "Мотоспортивна пам''ятка у Бельгії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Lake Robertville', 'Vodní plocha v Belgii — příjemný cíl vyjížďky s výhledy na hladinu.', 50.45, 6.11361, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Robertville%20%2C%20Pont%20Haelen.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Robertville%20%2C%20Pont%20Haelen.jpg"}'::text[], 1, '{"en": {"name": "Lake Robertville", "description": "Lake in Waimes, Wallonia, Belgium. A body of water in Belgium — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre Robertville", "description": "Stausee in Belgien. Ein Gewässer in Belgien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Lake Robertville", "description": "Zbiornik retencyjny (Waimes, Belgia). Akwen w Belgii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Robertville", "description": "Meer in België. Een waterpartij in België — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lake Robertville", "description": "Una masa de agua en Bélgica: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Robertville", "description": "Un plan d''eau en Belgique — une belle destination avec vue sur l''eau."}, "uk": {"name": "Lake Robertville", "description": "Водойма у Бельгії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Dam of the Vesdre', 'Vodní plocha v Belgii — příjemný cíl vyjížďky s výhledy na hladinu.', 50.61667, 6.09222, 'http://commons.wikimedia.org/wiki/Special:FilePath/Eupen002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Eupen002.jpg"}'::text[], 2, '{"en": {"name": "Dam of the Vesdre", "description": "Dam. A body of water in Belgium — a pleasant ride destination with waterside views."}, "de": {"name": "Wesertalsperre", "description": "Stausee in Belgien. Ein Gewässer in Belgien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Dam of the Vesdre", "description": "Zbiornik retencyjny (Eupen, Belgia). Akwen w Belgii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Weserstuwdam", "description": "Bouwwerk in Luik (provincie). Een waterpartij in België — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Dam of the Vesdre", "description": "Una masa de agua en Bélgica: un destino agradable con vistas al agua."}, "fr": {"name": "barrage de la Vesdre", "description": "Réservoir d''eau potable situé en Belgique. Un plan d''eau en Belgique — une belle destination avec vue sur l''eau."}, "uk": {"name": "Dam of the Vesdre", "description": "Водойма у Бельгії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Fort de Tancrémont', 'Hrad či zámek v Belgii — historická zastávka, která stojí za odbočku.', 50.55303, 5.79083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tancremont%20-%20fort%20-%20entry.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tancremont%20-%20fort%20-%20entry.jpg"}'::text[], 3, '{"en": {"name": "Fort de Tancrémont", "description": "Place in World War II in Belgium. A castle in Belgium — a historic stop worth the detour."}, "de": {"name": "Fort Tancremont", "description": "Befestigung aus dem ersten Weltkrieg. Eine Burg bzw. ein Schloss in Belgien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Grupa warowna Tancrémont", "description": "Zamek w Belgii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Fort Tancrémont", "description": "Plaats in de Tweede Wereldoorlog in België. Een kasteel in België — een historische stop die de omweg waard is."}, "es": {"name": "Fort de Tancrémont", "description": "Un castillo en Bélgica: una parada histórica que merece el desvío."}, "fr": {"name": "fort de Tancrémont", "description": "Un château en Belgique — une halte historique qui vaut le détour."}, "uk": {"name": "Форт Танкремон", "description": "Замок у Бельгії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'St James''s Church', 'Památka v Belgii — kus historie přímo u trasy.', 50.637, 5.57039, 'http://commons.wikimedia.org/wiki/Special:FilePath/LIEGE%20Eglise%20Saint-Jacques%20%2815%20-%202012%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/LIEGE%20Eglise%20Saint-Jacques%20%2815%20-%202012%29.JPG"}'::text[], 4, '{"en": {"name": "St James''s Church", "description": "Church in Liège, Belgium. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "St. Jakob (Lüttich)", "description": "Kirchengebäude in Wallonien, Belgien. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "St James''s Church", "description": "Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Jacobskerk", "description": "Kerkgebouw in Luik, België. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Abadía de Saint-Jacques", "description": "Iglesia en Bélgica. Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "église Saint-Jacques-le-Mineur de Liège", "description": "Édifice religieux belge. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "St James''s Church", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Liège Cathedral', 'Památka v Belgii — kus historie přímo u trasy.', 50.64028, 5.57167, 'http://commons.wikimedia.org/wiki/Special:FilePath/2022-08%20Cath%C3%A9drale%20Saint-Paul%20de%20Li%C3%A8ge%20-%20crop.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2022-08%20Cath%C3%A9drale%20Saint-Paul%20de%20Li%C3%A8ge%20-%20crop.jpg"}'::text[], 5, '{"en": {"name": "Liège Cathedral", "description": "Church in Liège, Belgium. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "St.-Pauls-Kathedrale", "description": "Kirchengebäude in Lüttich. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Świętego Pawła w Liège", "description": "Świątynia katolicka. Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Pauluskathedraal", "description": "Kerkgebouw in Luik, België. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Pablo", "description": "Edificio en Lieja, Bélgica. Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Paul de Liège", "description": "Édifice religieux belge. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "Льєзький собор", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'St. Lambert''s Cathedral', 'Památka v Belgii — kus historie přímo u trasy.', 50.64519, 5.57348, 'http://commons.wikimedia.org/wiki/Special:FilePath/Eglise-liege-stlambert-Deneumoulin-1780.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Eglise-liege-stlambert-Deneumoulin-1780.jpg"}'::text[], 6, '{"en": {"name": "St. Lambert''s Cathedral", "description": "Cathedral. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "Lambertuskathedrale Lüttich", "description": "Kirchengebäude in Lüttich. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Lamberta w Liège", "description": "Świątynia katolicka. Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Lambertuskathedraal", "description": "Luik. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Nuestra Señora y San Lamberto", "description": "Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame-et-Saint-Lambert de Liège", "description": "Cathédrale détruite de la ville de Liège. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "St. Lambert''s Cathedral", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb);
