    (v_route, 'Nürburgring', 'Automobilový závodní okruh (Německo). Motoristický cíl v Německu — rychlost, okruhy a legendy motorismu na dosah.', 50.33556, 6.9475, 'http://commons.wikimedia.org/wiki/Special:FilePath/ADAC%20GT%20Masters%20at%20Nuerburgring.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/ADAC%20GT%20Masters%20at%20Nuerburgring.jpg"}'::text[], 0, '{"en": {"name": "Nürburgring", "description": "Race track in Nürburg, Rhineland-Palatinate, Germany. A motorsport sight in Germany — speed, circuits and motoring legends within reach."}, "de": {"name": "Nürburgring", "description": "Rennstrecke in der Eifel, Rheinland-Pfalz, Deutschland. Ein Motorsport-Ziel in Deutschland — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Nürburgring", "description": "Cel motoryzacyjny w Niemczech — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Nürburgring", "description": "Racecircuit in Duitsland. Een autosportdoel in Duitsland — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Nürburgring", "description": "Autódromo alemán. Un destino del motor en Alemania: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "Nürburgring", "description": "Circuit automobile allemand. Un site du sport mécanique en Allemagne — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Нюрбургринг", "description": "Мотоспортивна пам''ятка в Німеччині — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Bürresheim Castle', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 50.3528, 7.17971, 'http://commons.wikimedia.org/wiki/Special:FilePath/Buerresheim%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Buerresheim%201.jpg"}'::text[], 1, '{"en": {"name": "Bürresheim Castle", "description": "Castle in Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Bürresheim", "description": "Schloss in Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Bürresheim", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Slot Bürresheim", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Bürresheim", "description": "Castillo en Alemania. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Bürresheim", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Bürresheim Castle", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Klášter Maria Laach', 'Benediktinské opatství bylo založeno roku 1093, zrušeno roku 1802 a obnoveno roku 1893 jako součást beuronské kongregace benediktinského řádu. Památka v Německu — kus historie přímo u trasy.', 50.40226, 7.2521, 'http://commons.wikimedia.org/wiki/Special:FilePath/00%201438%20Abteikirche%20Maria%20Laach.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/00%201438%20Abteikirche%20Maria%20Laach.jpg"}'::text[], 2, '{"en": {"name": "Maria Laach Abbey", "description": "Monastery in Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Benediktinerabtei Laach", "description": "Hochmittelalterliche Klosteranlage in der Eifel. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Maria Laach", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij Maria Laach", "description": "Klooster in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Abadía de Maria Laach", "description": "Abadía benedictina en Maria Laach, Glees, Renania-Palatinado, Alemania. Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Maria Laach", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Абатство Марії Лаах", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Laacherské jezero', 'Kalderové jezero ve spolkové zemi Porýní-Falc v Německu. Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 50.4125, 7.27, 'http://commons.wikimedia.org/wiki/Special:FilePath/Laacher%20See%20-%20Luftaufnahme.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Laacher%20See%20-%20Luftaufnahme.jpg"}'::text[], 3, '{"en": {"name": "Laacher See", "description": "Volcanic crater lake in Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Laacher See", "description": "Wassergefüllte Caldera in der Eifel. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Laacher See", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Laacher See", "description": "Kratermeer in de Eifel, Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Laach", "description": "Lago cráter/caldera en Alemania. Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Laach", "description": "Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Лаах (озеро)", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Eltz', 'Hrad v Německu. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 50.205, 7.33667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Eltz%20am%20fr%C3%BChen%20Morgen.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Eltz%20am%20fr%C3%BChen%20Morgen.jpg"}'::text[], 4, '{"en": {"name": "Eltz Castle", "description": "Castle in Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Burg Eltz", "description": "Burg in Rheinland-Pfalz, Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Eltz", "description": "Zamek w Niemczech. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Burg Eltz", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "castillo de Eltz", "description": "Castillo medieval en Alemania. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château d''Eltz", "description": "Château fort allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Ельц", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Reichsburg Cochem', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 50.1422, 7.16694, 'http://commons.wikimedia.org/wiki/Special:FilePath/Reichsburg%20Cochem.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Reichsburg%20Cochem.jpg"}'::text[], 5, '{"en": {"name": "Reichsburg Cochem", "description": "Fortification in Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Reichsburg Cochem", "description": "Burg an der Mosel, Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Reichsburg Cochem", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Rijksburcht Cochem", "description": "Fortificatie in Rijnland-Palts, Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Cochem", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "Reichsburg Cochem", "description": "Château perché en Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Reichsburg Cochem", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Prümské opatství', 'Německé opatství. Památka v Německu — kus historie přímo u trasy.', 50.20639, 6.42583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Abtei%2BBasilika%20von%20Norden%20o.%20Mauer.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Abtei%2BBasilika%20von%20Norden%20o.%20Mauer.jpg"}'::text[], 6, '{"en": {"name": "Prüm Abbey", "description": "Abbey. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Benediktinerabtei St. Salvator, Prüm", "description": "Ehemalige Abtei in Prüm, Rheinland-Pfalz. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Prüm", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Prüm", "description": "Abdij in Prüm, Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Prüm", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Prüm", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Прюмське абатство", "description": "Абатство в ФРН. Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb);
