    (v_route, 'Bazilika svatého Dominika', 'Kostel v Bologni. Památka v Itálii — kus historie přímo u trasy.', 44.4895, 11.3445, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bologna%20-%20Piazza%20San%20Domenico%20%28DSCN0004-01-01%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bologna%20-%20Piazza%20San%20Domenico%20%28DSCN0004-01-01%29.jpg"}'::text[], 1, '{"en": {"name": "Basilica of San Domenico", "description": "Major church in Bologna, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Basilika San Domenico", "description": "Kirchengebäude in Bologna, Italien. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazilika svatého Dominika", "description": "Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Basiliek van San Domenico", "description": "Basiliek in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Santo Domingo", "description": "De los principales lugares de culto de Bolonia y sede principal de la Orden Dominicana. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique San Domenico", "description": "Bâtiment historique de Bologne, en Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка святого Домініка", "description": "Церква у Болоньї, Італія. Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
