    (v_route, 'Autodromo Nazionale Monza', 'Motoristický okruh. Motoristický cíl v Itálii — rychlost, okruhy a legendy motorismu na dosah.', 45.62056, 9.28944, 'http://commons.wikimedia.org/wiki/Special:FilePath/1975%20Italian%20GP%20race%20start%20-%20Niki%20Lauda%20%26%20Clay%20Regazzoni%20%28Ferrari%20312T%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/1975%20Italian%20GP%20race%20start%20-%20Niki%20Lauda%20%26%20Clay%20Regazzoni%20%28Ferrari%20312T%29.jpg"}'::text[], 0, '{"en": {"name": "Monza Circuit", "description": "Motorsport racetrack in Monza, Italy. A motorsport sight in Italy — speed, circuits and motoring legends within reach."}, "de": {"name": "Autodromo Nazionale Monza", "description": "Motorsport-Rennstrecke in Italien. Ein Motorsport-Ziel in Italien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Autodromo Nazionale di Monza", "description": "Tor wyścigowy we Włoszech. Cel motoryzacyjny we Włoszech — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Autodromo Nazionale Monza", "description": "Circuit in Italië. Een autosportdoel in Italië — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Autodromo Nazionale di Monza", "description": "Circuito de carreras de Italia. Un destino del motor en Italia: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "Autodromo Nazionale di Monza", "description": "Circuit automobile italien. Un site du sport mécanique en Italie — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Монца", "description": "Мотоспортивна пам''ятка в Італії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
