    (v_route, 'Sforzesco', 'Hrad v Itálii. Hrad či zámek v Itálii — historická zastávka, která stojí za odbočku.', 45.471, 9.17969, 'http://commons.wikimedia.org/wiki/Special:FilePath/20110725%20Castello%20Sforzesco%20Milan%205557.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/20110725%20Castello%20Sforzesco%20Milan%205557.jpg"}'::text[], 2, '{"en": {"name": "Sforza Castle", "description": "Castle in Milan, Italy. A castle in Italy — a historic stop worth the detour."}, "de": {"name": "Castello Sforzesco", "description": "Schloss in Mailand. Eine Burg bzw. ein Schloss in Italien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Castello Sforzesco", "description": "Zamek w Mediolanie, Włochy. Zamek we Włoszech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castello Sforzesco", "description": "Museum in Milaan. Een kasteel in Italië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Sforzesco", "description": "Castillo que se encuentra en el casco antiguo de Milán, Italia. Un castillo en Italia: una parada histórica que merece el desvío."}, "fr": {"name": "château des Sforza", "description": "Château milanais. Un château en Italie — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Сфорца", "description": "Замок в Італії. Замок в Італії — історична зупинка, варта об''їзду."}}'::jsonb),
