    (v_route, 'Silverstone', 'Závodní okruh v Anglii. Motoristický cíl ve Velké Británii — rychlost, okruhy a legendy motorismu na dosah.', 52.075, -1.01667, 'http://commons.wikimedia.org/wiki/Special:FilePath/McLaren%20MP4-16A%202015%20McLaren%20MP4-16A%20shakedown%20%2821219267118%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/McLaren%20MP4-16A%202015%20McLaren%20MP4-16A%20shakedown%20%2821219267118%29.jpg"}'::text[], 0, '{"en": {"name": "Silverstone Circuit", "description": "Motor racing circuit on the Buckinghamshire and Northamptonshire border, UK. A motorsport sight in the United Kingdom — speed, circuits and motoring legends within reach."}, "de": {"name": "Silverstone Circuit", "description": "Motorsport-Rennstrecke in England. Ein Motorsport-Ziel in Großbritannien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Silverstone Circuit", "description": "Tor wyścigowy w Wielkiej Brytanii. Cel motoryzacyjny w Wielkiej Brytanii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Silverstone", "description": "Circuit. Een autosportdoel in het Verenigd Koninkrijk — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Circuito de Silverstone", "description": "Autódromo inglés. Un destino del motor en el Reino Unido: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "Circuit de Silverstone", "description": "Circuit automobile anglais. Un site du sport mécanique au Royaume-Uni — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Сільверстоун", "description": "Мотоспортивна пам''ятка у Великій Британії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Northampton Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 52.2371, -0.90489, 'http://commons.wikimedia.org/wiki/Special:FilePath/Northampton%20Castle%20Bastion.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Northampton%20Castle%20Bastion.jpg"}'::text[], 1, '{"en": {"name": "Northampton Castle", "description": "Castle in Northampton, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Northampton Castle", "description": "Schloss im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Northampton Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Northampton Castle", "description": "Kasteel in Northampton, het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Northampton Castle", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Northampton", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Northampton Castle", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
