    (v_route, 'Circuit de Catalunya', 'Motoristický cíl ve Španělsku — rychlost, okruhy a legendy motorismu na dosah.', 41.57, 2.26111, 'http://commons.wikimedia.org/wiki/Special:FilePath/F1%20Circuit%20de%20Catalunya%20-%20Tribuna.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/F1%20Circuit%20de%20Catalunya%20-%20Tribuna.jpg"}'::text[], 0, '{"en": {"name": "Circuit de Barcelona-Catalunya", "description": "Motorsport track in Spain. A motorsport sight in Spain — speed, circuits and motoring legends within reach."}, "de": {"name": "Circuit de Barcelona-Catalunya", "description": "Rennstrecke in Barcelona. Ein Motorsport-Ziel in Spanien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Circuit de Barcelona-Catalunya", "description": "Cel motoryzacyjny w Hiszpanii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Circuit de Catalunya", "description": "Circuit in Spanje. Een autosportdoel in Spanje — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Circuito de Cataluña", "description": "Circuito de carreras de España. Un destino del motor en España: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "Circuit de Catalogne", "description": "Circuit automobile espagnol. Un site du sport mécanique en Espagne — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Каталунья", "description": "Мотоспортивна пам''ятка в Іспанії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Sagrada Família', 'Chrám ve Španělsku. Památka ve Španělsku — kus historie přímo u trasy.', 41.40369, 2.17433, 'http://commons.wikimedia.org/wiki/Special:FilePath/SF%20maig%202026.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/SF%20maig%202026.jpg"}'::text[], 1, '{"en": {"name": "Basilica and Expiatory Church of the Holy Family", "description": "Basilica under construction since 1882 in Barcelona, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Sagrada Família", "description": "Römisch-katholische Basilika im Bau in Barcelona, Katalonien, Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sagrada Família", "description": "Bazylika w Barcelonie. Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sagrada Família", "description": "Basiliek in Barcelona, Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Templo Expiatorio de la Sagrada Familia", "description": "Basílica católica de estilo modernista catalán en construcción en Barcelona, Cataluña, España. Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "Sagrada Família", "description": "Basilique catholique romaine monumentale en construction depuis 1882 situé à Barcelone, Catalogne, Espagne. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Храм Святого Сімейства", "description": "Монументальна римо-католицька базиліка, що будується в Барселоні, Каталонія, Іспанія. Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
