    (v_route, 'Hockenheimring', 'Německý automobilový závodní okruh. Motoristický cíl v Německu — rychlost, okruhy a legendy motorismu na dosah.', 49.32778, 8.56583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kimi%20Raikkonen%20-%20Turn%201%20of%20the%20Hockenheimring%20-%202014%20German%20Grand%20Prix.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kimi%20Raikkonen%20-%20Turn%201%20of%20the%20Hockenheimring%20-%202014%20German%20Grand%20Prix.jpg"}'::text[], 0, '{"en": {"name": "Hockenheimring", "description": "German motor racing circuit. A motorsport sight in Germany — speed, circuits and motoring legends within reach."}, "de": {"name": "Hockenheimring Baden-Württemberg", "description": "Motorsport-Rennstrecke in Deutschland. Ein Motorsport-Ziel in Deutschland — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Hockenheimring", "description": "Cel motoryzacyjny w Niemczech — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Hockenheimring Baden-Württemberg", "description": "Circuit in Baden-Württemberg, Duitsland. Een autosportdoel in Duitsland — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Hockenheimring", "description": "Autódromo alemán. Un destino del motor en Alemania: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "Hockenheimring", "description": "Circuit automobile allemand. Un site du sport mécanique en Allemagne — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Автодром Гокенгаймринг", "description": "Мотоспортивна пам''ятка в Німеччині — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Schwetzingen Palace', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 49.38353, 8.56593, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schwetzingen%20BW%202014-07-22%2016-43-37.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schwetzingen%20BW%202014-07-22%2016-43-37.jpg"}'::text[], 1, '{"en": {"name": "Schwetzingen Palace", "description": "Palace in Schwetzingen, Germany, formerly the summer residence of the Electors Palatine. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Schwetzingen", "description": "Schloss in Schwetzingen/Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac w Schwetzingen", "description": "Muzeum w Niemczech. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Schwetzingen Castle", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Schwetzingen", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Schwetzingen", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Шветцингенський палац", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
