    (v_route, 'Katedrála Panny Marie a svatého Štěpána ve Špýru', 'Katedrála v Německu. Památka v Německu — kus historie přímo u trasy.', 49.31722, 8.4425, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Speyer%20Cathedral%20%28view%20from%20the%20southwest%29%20%28cropped%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Speyer%20Cathedral%20%28view%20from%20the%20southwest%29%20%28cropped%29.jpg"}'::text[], 3, '{"en": {"name": "Speyer Cathedral", "description": "Cathedral in Speyer, Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Speyerer Dom", "description": "Kathedrale in Speyer. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Spirze", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Speyer", "description": "Kathedraal in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Espira", "description": "Catedral situada en la ciudad alemana de Speyer. Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame-de-l''Assomption-et-Saint-Étienne de Spire", "description": "Église allemande. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Шпаєрський собор", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Karlsruhe Palace', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 49.0136, 8.40444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Karlsruhe%20asv2022-10%20img07%20Schloss%20Karlsruhe.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Karlsruhe%20asv2022-10%20img07%20Schloss%20Karlsruhe.jpg"}'::text[], 4, '{"en": {"name": "Karlsruhe Palace", "description": "Palace built by count Karl Wilhelm von Baden-Durlach. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Karlsruhe", "description": "Ehemalige Residenz der Markgrafen und Großherzöge von Baden. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Karlsruhe", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Karlsruhe Palace", "description": "Duits nationaal monument in Karlsruhe. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Karlsruhe", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Karlsruhe", "description": "Château à Karlsruhe. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Карлсруе (палац)", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'katedrála svatého Petra ve Wormsu', 'Katedrála v Německu. Památka v Německu — kus historie přímo u trasy.', 49.63028, 8.35972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Worms%20Dom%20Ostfassade%20Vierung2005-05-27a.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Worms%20Dom%20Ostfassade%20Vierung2005-05-27a.jpg"}'::text[], 5, '{"en": {"name": "Worms Cathedral", "description": "Cathedral in Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Wormser Dom", "description": "Bedeutendes Kirchengebäude in Worms. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Wormacji", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Worms", "description": "Kathedraal in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Worms", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Pierre de Worms", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Вормський собор", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Opatství Lorsch', 'Památka v Německu — kus historie přímo u trasy.', 49.65369, 8.56858, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lorsch.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lorsch.jpg"}'::text[], 6, '{"en": {"name": "Abbey and Altenmünster of Lorsch", "description": "UNESCO World Heritage Abbey of Lorsch in Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Abtei und Altenmünster des Klosters Lorsch", "description": "Benediktinerkloster und UNESCO-Welterbe in Hessen. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo i klasztor Altenmünster w Lorsch", "description": "Dawne opactwo benedyktyńskie w Niemczech. Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Lorsch", "description": "Klooster in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Lorsch", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye et Altenmünster de Lorsch", "description": "Abbaye de Lorsch en Allemagne, patrimoine Mondial de L‘UNESCO. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Лоршське абатство", "description": "Монастир у Німеччині, обєк спадщини ЮНЕСКО. Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb);
