    (v_route, 'Red Bull Ring', 'Motoristický závodní okruh F1 v Rakousku. Motoristický cíl v Rakousku — rychlost, okruhy a legendy motorismu na dosah.', 47.21972, 14.76472, 'http://commons.wikimedia.org/wiki/Special:FilePath/United%20Autosports%20ELMS%20Red%20Bull%20Ring%202017-218.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/United%20Autosports%20ELMS%20Red%20Bull%20Ring%202017-218.jpg"}'::text[], 0, '{"en": {"name": "Red Bull Ring", "description": "Motor racing track. A motorsport sight in Austria — speed, circuits and motoring legends within reach."}, "de": {"name": "Red Bull Ring", "description": "Rennstrecke in Österreich. Ein Motorsport-Ziel in Österreich — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Red Bull Ring", "description": "Cel motoryzacyjny w Austrii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Red Bull Ring", "description": "Circuit in Oostenrijk. Een autosportdoel in Oostenrijk — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Red Bull Ring", "description": "Autódromo austriaco. Un destino del motor en Austria: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "Circuit de Spielberg", "description": "Circuit automobile autrichien. Un site du sport mécanique en Autriche — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "А1-Ринг", "description": "Мотоспортивна пам''ятка в Австрії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
