    (v_route, 'klášter Göss', 'Opatství v Rakousku. Památka v Rakousku — kus historie přímo u trasy.', 47.3631, 15.0958, 'http://commons.wikimedia.org/wiki/Special:FilePath/Goess%20013.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Goess%20013.jpg"}'::text[], 5, '{"en": {"name": "Göss Abbey", "description": "Abbey. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Stift Göß", "description": "Ehemaliges Kloster der Benediktinerinnen in Göss, Stadtteil von Leoben, Steiermark. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "klášter Göss", "description": "Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij Göss", "description": "Abdij in Stiermarken, Oostenrijk. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Göss", "description": "Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Göss", "description": "Abbaye. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "klášter Göss", "description": "Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
