    (v_route, 'Circuit Paul-Ricard', 'Závodní okruh formule 1 ve Francii. Motoristický cíl ve Francii — rychlost, okruhy a legendy motorismu na dosah.', 43.25056, 5.79167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Circuit%20Paul%20Ricard%20CPR.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Circuit%20Paul%20Ricard%20CPR.jpg"}'::text[], 0, '{"en": {"name": "Circuit Paul Ricard", "description": "French race track. A motorsport sight in France — speed, circuits and motoring legends within reach."}, "de": {"name": "Circuit Paul Ricard", "description": "Rennstrecke nahe Le Castellet, Südffrankreich. Ein Motorsport-Ziel in Frankreich — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Circuit Paul Ricard", "description": "Cel motoryzacyjny we Francji — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Circuit Paul Ricard", "description": "Circuit in Frankrijk. Een autosportdoel in Frankrijk — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Circuito Paul Ricard", "description": "Autódromo francés. Un destino del motor en Francia: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit Paul-Ricard", "description": "Circuit automobile français. Un site du sport mécanique en France — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Поль Рікар", "description": "Мотоспортивна пам''ятка у Франції — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Národní park Calanques', 'Francouzský národní park. Přírodní zajímavost ve Francii — místo na protažení nohou uprostřed přírody.', 43.20944, 5.44917, 'http://commons.wikimedia.org/wiki/Special:FilePath/En-Vau%20calanque%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/En-Vau%20calanque%201.jpg"}'::text[], 1, '{"en": {"name": "Calanques National Park", "description": "National park in France. A natural sight in France — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Calanques", "description": "Eine Natursehenswürdigkeit in Frankreich — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Calanques", "description": "Atrakcja przyrodnicza we Francji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Calanques Nationaal Park", "description": "Nationaal park in Frankrijk. Een natuurbezienswaardigheid in Frankrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Calanques", "description": "Área protegida de Francia. Un paraje natural en Francia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national des Calanques", "description": "Parc national français à la fois terrestre et marin. Un site naturel en France — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Каланки", "description": "Природна пам''ятка у Франції — місце розім''яти ноги серед природи."}}'::jsonb),
