    (v_route, 'Notre-Dame de la Garde', 'Památka ve Francii — kus historie přímo u trasy.', 43.28395, 5.37123, 'http://commons.wikimedia.org/wiki/Special:FilePath/Notre%20Dame%20de%20la%20Garde%20%E5%AE%88%E8%AD%B7%E8%81%96%E6%AF%8D%E9%99%A2%20-%20panoramio%20%281%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Notre%20Dame%20de%20la%20Garde%20%E5%AE%88%E8%AD%B7%E8%81%96%E6%AF%8D%E9%99%A2%20-%20panoramio%20%281%29.jpg"}'::text[], 3, '{"en": {"name": "Notre-Dame de la Garde", "description": "Basilica located in Bouches-du-Rhône, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Notre-Dame de la Garde", "description": "Kirchengebäude in Marseille, Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Notre Dame de la Garde w Marsylii", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Notre-Dame-de-la-Garde", "description": "Bouwwerk in Marseille. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Notre-Dame de la Garde", "description": "Basílica situada en Marsella (Francia). Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Notre-Dame-de-la-Garde", "description": "Basilique située à Marseille dans les Bouches-du-Rhône, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Нотр-Дам-де-ля-Гард", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
