    (v_route, 'D''If', 'Ostrovní pevnost poblíž Marseille. Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 43.27986, 5.32514, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20d%27If%20%40%20Baie%20de%20Marseille%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20d%27If%20%40%20Baie%20de%20Marseille%2001.jpg"}'::text[], 6, '{"en": {"name": "Château d''If", "description": "Fortification near Marseille, France. A castle in France — a historic stop worth the detour."}, "de": {"name": "Château d’If", "description": "Festung und ehemaliges Gefängnis auf einer Felseninsel vor der Küste von Marseille. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek d''If", "description": "Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Château d''If", "description": "Bouwwerk in Marseille. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de If", "description": "Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "château d''If", "description": "Forteresse française sur l''îlot d''If de l''archipel du Frioul au centre de la rade de Marseille. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "замок Іф", "description": "Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb);
