    (v_route, 'Circuito do Estoril', 'Motoristický cíl v Portugalsku — rychlost, okruhy a legendy motorismu na dosah.', 38.75083, -9.39417, 'http://commons.wikimedia.org/wiki/Special:FilePath/SL%20Estoril.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/SL%20Estoril.jpg"}'::text[], 0, '{"en": {"name": "Circuito do Estoril", "description": "Motorsport track in Portugal. A motorsport sight in Portugal — speed, circuits and motoring legends within reach."}, "de": {"name": "Circuito do Estoril", "description": "Rennstrecke in Portugal. Ein Motorsport-Ziel in Portugal — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Autódromo do Estoril", "description": "Tor wyścigowy (Portugalia). Cel motoryzacyjny w Portugalii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Autódromo do Estoril", "description": "Circuit in Portugal. Een autosportdoel in Portugal — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Autódromo do Estoril", "description": "Circuito de carreras de Portugal. Un destino del motor en Portugal: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit d''Estoril", "description": "Circuit automobile portugais. Un site du sport mécanique au Portugal — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Автодром Ештуріл", "description": "Мотоспортивна пам''ятка в Португалії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Maurský hrad', 'Středověký hrad v portugalské obci Sintra. Hrad či zámek v Portugalsku — historická zastávka, která stojí za odbočku.', 38.79254, -9.3896, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castelo%20dos%20Mouros.%20Sintra%2C%20Portugal.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castelo%20dos%20Mouros.%20Sintra%2C%20Portugal.jpg"}'::text[], 1, '{"en": {"name": "Castle of the Moors", "description": "Cultural heritage monument in Sintra, Portugal. A castle in Portugal — a historic stop worth the detour."}, "de": {"name": "Castelo dos Mouros", "description": "Burg in Portugal. Eine Burg bzw. ein Schloss in Portugal — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Maurów", "description": "Zamek w Portugalii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castelo dos Mouros", "description": "Kasteel in Sintra, Portugal. Een kasteel in Portugal — een historische stop die de omweg waard is."}, "es": {"name": "Castelo dos Mouros (Sintra)", "description": "Un castillo en Portugal: una parada histórica que merece el desvío."}, "fr": {"name": "château des Maures", "description": "Bâtiment de Sintra, Lisbonne, au Portugal. Un château au Portugal — une halte historique qui vaut le détour."}, "uk": {"name": "Замок маврів", "description": "Замок в Португалії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Palác Mafra', 'Monumentální komplex královského paláce a kláštera s bazilikou ve stejnojmenné obci v Portugalsku. Památka v Portugalsku — kus historie přímo u trasy.', 38.93692, -9.32639, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mafra%20May%202013-2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mafra%20May%202013-2.jpg"}'::text[], 2, '{"en": {"name": "Palace of Mafra", "description": "Church building in Mafra, Lisbon District, Portugal. A heritage sight in Portugal — a piece of history right on your route."}, "de": {"name": "Palácio Nacional de Mafra", "description": "Schloss in Mafra, größte Schloss- und Klosteranlage Portugals, mit Museum. Ein Denkmal in Portugal — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Pałac w Mafrze", "description": "Zabytek w Portugalii — kawałek historii tuż przy trasie."}, "nl": {"name": "Paleis van Mafra", "description": "Klooster in Portugal. Een monument in Portugal — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Palacio Nacional de Mafra", "description": "Un monumento en Portugal: un pedazo de historia junto a la ruta."}, "fr": {"name": "palais National de Mafra", "description": "Palais de Mafra, Lisbonne, Portugal. Un monument au Portugal — un morceau d''histoire au bord de la route."}, "uk": {"name": "Національний палац Мафра", "description": "Пам''ятка в Португалії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Klášter svatého Jeronýma', 'Klášter v Lisabonu. Památka v Portugalsku — kus historie přímo u trasy.', 38.69785, -9.2056, 'http://commons.wikimedia.org/wiki/Special:FilePath/1502%20legte%20K%C3%B6nig%20Manuel%20I.%20den%20Grundstein%20f%C3%BCr%20das%20Hieronymus%20Kloster%20in%20Lissabon.%2006.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/1502%20legte%20K%C3%B6nig%20Manuel%20I.%20den%20Grundstein%20f%C3%BCr%20das%20Hieronymus%20Kloster%20in%20Lissabon.%2006.jpg"}'::text[], 3, '{"en": {"name": "Jerónimos Monastery", "description": "Building in Santa Maria de Belém, Lisbon District, Portugal. A heritage sight in Portugal — a piece of history right on your route."}, "de": {"name": "Mosteiro dos Jerónimos", "description": "Kirchengebäude in Lissabon. Ein Denkmal in Portugal — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "klasztor Hieronimitów", "description": "Klasztor w Lizbonie. Zabytek w Portugalii — kawałek historii tuż przy trasie."}, "nl": {"name": "Mosteiro dos Jerónimos", "description": "Abdij in Lissabon, Portugal. Een monument in Portugal — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio de los Jerónimos de Belém", "description": "Monumento en Lisboa, Portugal. Un monumento en Portugal: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère des Hiéronymites", "description": "Monastère portugais du quartier de Belém, Lisbonne, Portugal. Un monument au Portugal — un morceau d''histoire au bord de la route."}, "uk": {"name": "Жеронімуш", "description": "Монастир в Лісабоні, Португалія. Пам''ятка в Португалії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Belémská věž', 'Opevněná věž v Lisabonu. Hrad či zámek v Portugalsku — historická zastávka, která stojí za odbočku.', 38.69139, -9.21583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Belem%20Tower%20-%20April%202019%20%282%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Belem%20Tower%20-%20April%202019%20%282%29.jpg"}'::text[], 4, '{"en": {"name": "Belém Tower", "description": "Fortified tower located in the civil parish of Santa Maria de Belém in the municipality of Lisbon, Portugal. A castle in Portugal — a historic stop worth the detour."}, "de": {"name": "Torre de Belém", "description": "Wahrzeichen Lissabons. Eine Burg bzw. ein Schloss in Portugal — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Torre de Belém", "description": "Wieża warowna (Lizbona, Portugalia). Zamek w Portugalii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Torre de Belém", "description": "Bouwwerk in Lissabon. Een kasteel in Portugal — een historische stop die de omweg waard is."}, "es": {"name": "Torre de Belém", "description": "Torre de defensa militar en Lisboa. Un castillo en Portugal: una parada histórica que merece el desvío."}, "fr": {"name": "tour de Belém", "description": "Bâtiment de Santa Maria de Belém, Lisbonne, au Portugal. Un château au Portugal — une halte historique qui vaut le détour."}, "uk": {"name": "Беленська башта", "description": "Укріплена ренесансна башта в районі Белен на березі р.Тежу. Замок в Португалії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Lisabonská katedrála', 'Památka v Portugalsku — kus historie přímo u trasy.', 38.70985, -9.13298, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lisboa%20May%202013-1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lisboa%20May%202013-1.jpg"}'::text[], 5, '{"en": {"name": "Lisbon Cathedral", "description": "Roman Catholic Cathedral located in Lisbon, Portugal. A heritage sight in Portugal — a piece of history right on your route."}, "de": {"name": "Kathedrale von Lissabon", "description": "Kirchengebäude in Lissabon. Ein Denkmal in Portugal — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Sé w Lizbonie", "description": "Zabytek w Portugalii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Lissabon", "description": "Bouwwerk in Lissabon. Een monument in Portugal — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Lisboa", "description": "Un monumento en Portugal: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Santa Maria Maior de Lisbonne", "description": "Cathédrale catholique romaine de Lisbonne, Portugal. Un monument au Portugal — un morceau d''histoire au bord de la route."}, "uk": {"name": "Лісабонський собор", "description": "Пам''ятка в Португалії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Hrad svatého Jiří', 'Hrad v Lisabonu. Hrad či zámek v Portugalsku — historická zastávka, která stojí za odbočku.', 38.71389, -9.13333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castelo%20de%20S%C3%A3o%20Jorge%20%284166049903%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castelo%20de%20S%C3%A3o%20Jorge%20%284166049903%29.jpg"}'::text[], 6, '{"en": {"name": "Castle of Saint George", "description": "Moorish castle in Lisbon, Portugal. A castle in Portugal — a historic stop worth the detour."}, "de": {"name": "Castelo de São Jorge", "description": "Burg in Portugal. Eine Burg bzw. ein Schloss in Portugal — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek św. Jerzego w Lizbonie", "description": "Zamek w Portugalii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castelo de São Jorge", "description": "Bouwwerk in Lissabon. Een kasteel in Portugal — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de San Jorge de Lisboa", "description": "Castillo en Lisboa, Portugal. Un castillo en Portugal: una parada histórica que merece el desvío."}, "fr": {"name": "château de Saint-Georges", "description": "Château mauresque à Lisbonne. Un château au Portugal — une halte historique qui vaut le détour."}, "uk": {"name": "Замок святого георгія", "description": "Замок в Португалії — історична зупинка, варта об''їзду."}}'::jsonb);
