    (v_route, 'Valencia Street Circuit', 'Motoristický cíl ve Španělsku — rychlost, okruhy a legendy motorismu na dosah.', 39.45767, -0.33163, 'http://commons.wikimedia.org/wiki/Special:FilePath/Swing-bridge%20Valencia%20Street%20Circuit.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Swing-bridge%20Valencia%20Street%20Circuit.jpg"}'::text[], 0, '{"en": {"name": "Valencia Street Circuit", "description": "Motorsport track in Spain. A motorsport sight in Spain — speed, circuits and motoring legends within reach."}, "de": {"name": "Valencia Street Circuit", "description": "Ein Motorsport-Ziel in Spanien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Valencia Street Circuit", "description": "Hiszpański tor wyścigowy. Cel motoryzacyjny w Hiszpanii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Valencia Street Circuit", "description": "Circuit in Spanje. Een autosportdoel in Spanje — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "circuito urbano de Valencia", "description": "Circuito abandonado de carreras de España. Un destino del motor en España: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit urbain de Valence", "description": "Ancien circuit automobile espagnol. Un site du sport mécanique en Espagne — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Валенсія", "description": "Мотоспортивна пам''ятка в Іспанії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
