    (v_route, 'Albufera of Valencia', 'Vodní plocha ve Španělsku — příjemný cíl vyjížďky s výhledy na hladinu.', 39.33167, -0.35222, 'http://commons.wikimedia.org/wiki/Special:FilePath/Albufera%20de%20valencia%20SatNASA.png', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Albufera%20de%20valencia%20SatNASA.png"}'::text[], 5, '{"en": {"name": "Albufera of Valencia", "description": "Coastal lagoon in Spain. A body of water in Spain — a pleasant ride destination with waterside views."}, "de": {"name": "Albufera Valenciana", "description": "Strandsee (eine ausgesüßte Lagune) an der Küste des Golfs von Valencia in der Autonomen Gemeinschaft Valencia im Osten Spaniens. Ein Gewässer in Spanien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Albufera of Valencia", "description": "Akwen w Hiszpanii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Albufera of Valencia", "description": "Een waterpartij in Spanje — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Albufera de Valencia", "description": "Laguna costera. Una masa de agua en España: un destino agradable con vistas al agua."}, "fr": {"name": "Albufera of Valencia", "description": "Un plan d''eau en Espagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Albufera of Valencia", "description": "Водойма в Іспанії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
