    (v_route, 'Okruh Mugello', 'Závodní okruh v Itálii. Motoristický cíl v Itálii — rychlost, okruhy a legendy motorismu na dosah.', 43.9975, 11.37194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Partenza%20del%20Gran%20Premio%20d%27Italia%20TIM%202011.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Partenza%20del%20Gran%20Premio%20d%27Italia%20TIM%202011.jpg"}'::text[], 0, '{"en": {"name": "Mugello Circuit", "description": "Motorsport venue in Italy. A motorsport sight in Italy — speed, circuits and motoring legends within reach."}, "de": {"name": "Autodromo Internazionale del Mugello", "description": "Italienische Motorsportrennstrecke. Ein Motorsport-Ziel in Italien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Mugello Circuit", "description": "Tor wyścigowy (Włochy). Cel motoryzacyjny we Włoszech — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Circuit Mugello", "description": "Circuit in Italië. Een autosportdoel in Italië — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Autódromo Internacional del Mugello", "description": "Circuito de carreras de Italia. Un destino del motor en Italia: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit du Mugello", "description": "Circuit automobile italien. Un site du sport mécanique en Italie — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Муджелло", "description": "Мотоспортивна пам''ятка в Італії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Bazilika svatého Vavřince ve Florencii', 'Kostel ve Florencii. Památka v Itálii — kus historie přímo u trasy.', 43.775, 11.25389, 'http://commons.wikimedia.org/wiki/Special:FilePath/Florencia%2C%20Italia%20-%20panoramio%20%282%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Florencia%2C%20Italia%20-%20panoramio%20%282%29.jpg"}'::text[], 1, '{"en": {"name": "Basilica of San Lorenzo", "description": "Church in Florence, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Basilika San Lorenzo", "description": "Kirchengebäude in Florenz. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika San Lorenzo", "description": "Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Laurensbasiliek", "description": "Kerkgebouw in Florence. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Lorenzo de Florencia", "description": "Iglesia católica en Florencia, Italia. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique San Lorenzo", "description": "Église à Florence, Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Сан-Лоренцо", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
