    (v_route, 'Scandinavian Raceway', 'Závodní dráha v Anderstorpu ve Švédsku. Motoristický cíl ve Švédsku — rychlost, okruhy a legendy motorismu na dosah.', 57.26417, 13.60139, 'http://commons.wikimedia.org/wiki/Special:FilePath/Swedish%20Grand%20Prix%201973%20%28JOKAMAL3B08-14%29.tif', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Swedish%20Grand%20Prix%201973%20%28JOKAMAL3B08-14%29.tif"}'::text[], 0, '{"en": {"name": "Anderstorp Raceway", "description": "Motorsport track in Sweden. A motorsport sight in Sweden — speed, circuits and motoring legends within reach."}, "de": {"name": "Anderstorp Raceway", "description": "Rennstrecke in Schweden. Ein Motorsport-Ziel in Schweden — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Scandinavian Raceway", "description": "Tor wyścigowy (Szwecja). Cel motoryzacyjny w Szwecji — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Scandinavian Raceway", "description": "Circuit in Gislaved, Zweden. Een autosportdoel in Zweden — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Scandinavian Raceway", "description": "Circuito de carreras de Suecia. Un destino del motor en Suecia: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit de Scandinavie", "description": "Circuit automobile suédois. Un site du sport mécanique en Suède — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Андерсторп", "description": "Мотоспортивна пам''ятка у Швеції — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Store Mosse National Park', 'Přírodní zajímavost ve Švédsku — místo na protažení nohou uprostřed přírody.', 57.28494, 13.94383, 'http://commons.wikimedia.org/wiki/Special:FilePath/Store%20Mosse%20nationalpark%20%28sp%C3%A5ng%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Store%20Mosse%20nationalpark%20%28sp%C3%A5ng%29.jpg"}'::text[], 1, '{"en": {"name": "Store Mosse National Park", "description": "National park. A natural sight in Sweden — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Store Mosse", "description": "Nationalpark in Schweden. Eine Natursehenswürdigkeit in Schweden — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Store Mosse", "description": "Park narodowy w Szwecji. Atrakcja przyrodnicza w Szwecji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal park Store Mosse", "description": "Natuurgebied in Zweden. Een natuurbezienswaardigheid in Zweden — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Store Mosse", "description": "Parque nacional en Suecia. Un paraje natural en Suecia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Store Mosse", "description": "Parc national de Suède. Un site naturel en Suède — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Store Mosse National Park", "description": "Природна пам''ятка у Швеції — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Hindsen', 'Vodní plocha ve Švédsku — příjemný cíl vyjížďky s výhledy na hladinu.', 57.1882, 14.1536, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hindsen%20Sj%C3%B6n.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hindsen%20Sj%C3%B6n.JPG"}'::text[], 2, '{"en": {"name": "Hindsen", "description": "Lake in Sweden. A body of water in Sweden — a pleasant ride destination with waterside views."}, "de": {"name": "Hindsen", "description": "Ein Gewässer in Schweden — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Hindsen", "description": "Akwen w Szwecji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Hindsen", "description": "Meer in Zweden. Een waterpartij in Zweden — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Hindsen", "description": "Una masa de agua en Suecia: un destino agradable con vistas al agua."}, "fr": {"name": "Hindsen", "description": "Lac en Suède. Un plan d''eau en Suède — une belle destination avec vue sur l''eau."}, "uk": {"name": "Hindsen", "description": "Водойма у Швеції — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Vidöstern', 'Vodní plocha ve Švédsku — příjemný cíl vyjížďky s výhledy na hladinu.', 57.06669, 14.02, 'http://commons.wikimedia.org/wiki/Special:FilePath/0062F%C3%A4rjans%20%C3%B6.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/0062F%C3%A4rjans%20%C3%B6.jpg"}'::text[], 3, '{"en": {"name": "Vidöstern", "description": "Lake in Sweden. A body of water in Sweden — a pleasant ride destination with waterside views."}, "de": {"name": "Vidöstern", "description": "See in Schweden. Ein Gewässer in Schweden — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Vidöstern", "description": "Akwen w Szwecji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vidöstern", "description": "Meer in Zweden. Een waterpartij in Zweden — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vidöstern", "description": "Una masa de agua en Suecia: un destino agradable con vistas al agua."}, "fr": {"name": "Vidöstern", "description": "Lac suédois. Un plan d''eau en Suède — une belle destination avec vue sur l''eau."}, "uk": {"name": "Vidöstern", "description": "Озеро у Швеції. Водойма у Швеції — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
