    (v_route, 'Circuit Ricardo Tormo', 'Motoristický cíl ve Španělsku — rychlost, okruhy a legendy motorismu na dosah.', 39.48583, -0.62806, 'http://commons.wikimedia.org/wiki/Special:FilePath/FIM%20CEV%20Repsol%20Valencia%20Round%20II%20%2825%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/FIM%20CEV%20Repsol%20Valencia%20Round%20II%20%2825%29.jpg"}'::text[], 0, '{"en": {"name": "Circuit Ricardo Tormo", "description": "Motorsport track in Spain. A motorsport sight in Spain — speed, circuits and motoring legends within reach."}, "de": {"name": "Circuit Ricardo Tormo", "description": "Motorsport-Rennstrecke in Cheste, Spanien. Ein Motorsport-Ziel in Spanien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Circuit Ricardo Tormo", "description": "Tor wyścigowy (Hiszpania). Cel motoryzacyjny w Hiszpanii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Circuit Ricardo Tormo Valencia", "description": "Circuit in Spanje. Een autosportdoel in Spanje — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Circuito Ricardo Tormo", "description": "Circuito de carreras de España. Un destino del motor en España: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit de Valence", "description": "Circuit automobile espagnol. Un site du sport mécanique en Espagne — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Траса імені Рікардо Тормо", "description": "Мотоспортивна пам''ятка в Іспанії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
