    (v_route, 'BMW Museum', 'Muzeum v Mnichově. Motoristický cíl v Německu — rychlost, okruhy a legendy motorismu na dosah.', 48.17667, 11.55917, 'http://commons.wikimedia.org/wiki/Special:FilePath/Museo%20BMW%2C%20M%C3%BAnich%2C%20Alemania%202012-04-28%2C%20DD%2001.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Museo%20BMW%2C%20M%C3%BAnich%2C%20Alemania%202012-04-28%2C%20DD%2001.JPG"}'::text[], 0, '{"en": {"name": "BMW Museum", "description": "Museum in Germany. A motorsport sight in Germany — speed, circuits and motoring legends within reach."}, "de": {"name": "BMW-Museum", "description": "Museum in Deutschland. Ein Motorsport-Ziel in Deutschland — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Muzeum BMW", "description": "Muzeum w Niemczech. Cel motoryzacyjny w Niemczech — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "BMW Museum", "description": "Bouwwerk in München. Een autosportdoel in Duitsland — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Museo BMW", "description": "Un destino del motor en Alemania: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "musée BMW", "description": "Musée en Allemagne. Un site du sport mécanique en Allemagne — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Музей BMW", "description": "Музей у Німеччині. Мотоспортивна пам''ятка в Німеччині — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Královská rezidence Mnichov', 'Městský zámek a rezidence bavorských vévodů, kurfiřtů a králů. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.14105, 11.57871, 'http://commons.wikimedia.org/wiki/Special:FilePath/BAVIERA.%20M%C3%9ANICH.%20Residenz%20%28fachada%20occidental%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/BAVIERA.%20M%C3%9ANICH.%20Residenz%20%28fachada%20occidental%29.jpg"}'::text[], 1, '{"en": {"name": "Munich Residence", "description": "Building in Munich, Upper Bavaria, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Residenz München", "description": "Größtes Innenstadtschloss Deutschlands. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Rezydencja w Monachium", "description": "Rezydencja królów Bawarii. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Munich Residenz", "description": "Stadsresidentie in classicistische stijl in de Duitse stad München. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Residencia de Múnich", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "résidence de Munich", "description": "Bâtiment de Munich, Haute-Bavière, Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Мюнхенська Резиденція", "description": "Будівля у Верхній Баварії, Німеччина. Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála Panny Marie v Mnichově', 'Katedrála v německém Mnichově. Památka v Německu — kus historie přímo u trasy.', 48.13858, 11.57362, 'http://commons.wikimedia.org/wiki/Special:FilePath/Frauenkirche%20Munich%20-%20View%20from%20Peterskirche%20Tower.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Frauenkirche%20Munich%20-%20View%20from%20Peterskirche%20Tower.jpg"}'::text[], 2, '{"en": {"name": "Frauenkirche", "description": "Church in Munich, Bavaria, Germany; cathedral of the archdiocese of Munich and Freising. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Frauenkirche, München", "description": "Kathedralkirche des katholischen Erzbistums München und Freising, Deutschland. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Najświętszej Marii Panny w Monachium", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Frauenkirche", "description": "München. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Nuestra Señora de Múnich", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame de Munich", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Фрауенкірхе", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
