    (v_route, 'Schleißheim palace complex', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.24861, 11.56833, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Schleissheim%20Palace.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Schleissheim%20Palace.jpg"}'::text[], 4, '{"en": {"name": "Schleißheim palace complex", "description": "Comprises three palaces in a grand baroque park in the village of Oberschleißheim near Munich, Bavaria, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schlossanlage Schleißheim", "description": "Schlosskomplex mit drei Schlössern in Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Schleißheim", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Paleis van Schleißheim", "description": "Duits kastelencomplex. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Schleißheim", "description": "Complejo palaciego alemán. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Schleissheim", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Палац Шляйсгайм", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Starnberské jezero', 'Jezero v Horním Bavorsku. Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 47.90389, 11.30722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Starnberg%20%28view%20from%20the%20south%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Starnberg%20%28view%20from%20the%20south%29.jpg"}'::text[], 5, '{"en": {"name": "Lake Starnberg", "description": "Lake in Bavaria, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Starnberger See", "description": "See in Bayern. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Starnberger See", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Starnberger See", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Starnberg", "description": "Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Starnberg", "description": "5e plus grand lac d''Allemagne. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Штарнбергер-Зее", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Ammersee', 'Jezero v Bavorsku. Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 48.0, 11.11667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Ammersee%20%28view%20from%20the%20south%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Ammersee%20%28view%20from%20the%20south%29.jpg"}'::text[], 6, '{"en": {"name": "Ammersee", "description": "Lake in Upper Bavaria, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Ammersee", "description": "See in Oberbayern (Landkreise Landsberg am Lech und Weilheim-Schongau). Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Ammer", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Ammersee", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Ammer", "description": "Lago en la Alta Baviera, Alemania. Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "lac Ammer", "description": "Lac allemand. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Аммерзее", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
