    (v_route, 'Reims-Gueux', 'Závodní okruh ve Francii. Motoristický cíl ve Francii — rychlost, okruhy a legendy motorismu na dosah.', 49.25417, 3.93083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dodge-challenger-srt8-at-reims-track.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dodge-challenger-srt8-at-reims-track.jpg"}'::text[], 0, '{"en": {"name": "Reims-Gueux", "description": "Race track. A motorsport sight in France — speed, circuits and motoring legends within reach."}, "de": {"name": "Circuit de Reims-Gueux", "description": "Motorsport-Strecke in Frankreich. Ein Motorsport-Ziel in Frankreich — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Reims-Gueux", "description": "Tor wyścigowy (Francja). Cel motoryzacyjny we Francji — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Circuit de Reims-Gueux", "description": "Circuit in Gueux, Frankrijk. Een autosportdoel in Frankrijk — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Reims-Gueux", "description": "Circuito de carreras en Reims, Francia. Un destino del motor en Francia: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit de Reims-Gueux", "description": "Ancien circuit automobile français. Un site du sport mécanique en France — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Реймс-Ге (траса)", "description": "Мотоспортивна пам''ятка у Франції — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
