    (v_route, 'Aintree Motor Racing Circuit', 'Automobilový závodní okruh ve Velké Británii. Motoristický cíl ve Velké Británii — rychlost, okruhy a legendy motorismu na dosah.', 53.47694, -2.94056, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vanwall%20VW5%20Aintree%201957.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vanwall%20VW5%20Aintree%201957.jpg"}'::text[], 0, '{"en": {"name": "Aintree Motor Racing Circuit", "description": "Race track in Merseyside, UK. A motorsport sight in the United Kingdom — speed, circuits and motoring legends within reach."}, "de": {"name": "Aintree Motor Racing Circuit", "description": "Ein Motorsport-Ziel in Großbritannien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Aintree Motor Racing Circuit", "description": "Tor wyścigowy (Wielka Brytania). Cel motoryzacyjny w Wielkiej Brytanii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Aintree Motor Racing Circuit", "description": "Circuit in het Verenigd Koninkrijk. Een autosportdoel in het Verenigd Koninkrijk — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Circuito de Aintree", "description": "Un destino del motor en el Reino Unido: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit d''Aintree", "description": "Circuit automobile anglais. Un site du sport mécanique au Royaume-Uni — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Ейнтрі (траса)", "description": "Мотоспортивна пам''ятка у Великій Британії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Liverpoolská metropolitní katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 53.40472, -2.96889, 'http://commons.wikimedia.org/wiki/Special:FilePath/Liverpool%20Metropolitan%20Cathedral%2002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Liverpool%20Metropolitan%20Cathedral%2002.jpg"}'::text[], 1, '{"en": {"name": "Liverpool Metropolitan Cathedral", "description": "Catholic cathedral. seat of the Archbishop of Liverpool in England. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Liverpool Metropolitan Cathedral", "description": "Kirche in Liverpool, England. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Metropolitarna w Liverpoolu", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Liverpool Metropolitan Cathedral", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral Metropolitana de Liverpool", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale métropolitaine du Christ-Roi de Liverpool", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Liverpoolská metropolitní katedrála", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Liverpoolská katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 53.39751, -2.97305, 'http://commons.wikimedia.org/wiki/Special:FilePath/LIVERPOOL%20ANGLICAN%20CATHEDRAL%20SEP2012%20%287916053494%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/LIVERPOOL%20ANGLICAN%20CATHEDRAL%20SEP2012%20%287916053494%29.jpg"}'::text[], 2, '{"en": {"name": "Liverpool Cathedral", "description": "Cathedral of the Diocese of Liverpool, Merseyside, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Liverpool Cathedral", "description": "Neogotische Kathedrale in der englischen Stadt Liverpool. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Liverpoolu", "description": "Neogotycka anglikańska katedra w Liverpoolu. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Liverpool", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Liverpool", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Liverpool", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Liverpoolská katedrála", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Halton Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 53.33306, -2.69583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Halton%20Castle%20%285%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Halton%20Castle%20%285%29.JPG"}'::text[], 3, '{"en": {"name": "Halton Castle", "description": "Ruins of castle with later buildings in Halton, Cheshire, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Halton Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Halton Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Halton Castle", "description": "Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Halton", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Halton", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Halton Castle", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Chesterská katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 53.19194, -2.89056, 'http://commons.wikimedia.org/wiki/Special:FilePath/Chester%20Cathedral%20ext%20Hamilton%20005.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Chester%20Cathedral%20ext%20Hamilton%20005.JPG"}'::text[], 4, '{"en": {"name": "Chester Cathedral", "description": "Grade I listed cathedral in Chester, United Kingdom. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Chester Cathedral", "description": "Kirchengebäude in Cheshire West and Chester, England. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Chester", "description": "Katedra katedralna kościoła anglikańskiego. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Chester", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Chester", "description": "Catedral de culto anglicano. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Chester", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Chesterská katedrála", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
