    (v_route, 'Blackpool Tower', 'Ocelová věž v britském Blackpoolu. Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 53.81583, -3.05528, 'http://commons.wikimedia.org/wiki/Special:FilePath/Blackpool%20Tower%20Buildings.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Blackpool%20Tower%20Buildings.jpg"}'::text[], 6, '{"en": {"name": "Blackpool Tower", "description": "Observation tower and entertainment complex in Blackpool, Lancashire, England, UK. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "Blackpool Tower", "description": "Aussichtsturm und Theater im Vereinigten Königreich. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Blackpool Tower", "description": "Wieża widokowa w Blackpoolu. Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Blackpool Tower", "description": "Uitkijktoren in het Verenigd Koninkrijk. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre de Blackpool", "description": "Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour de Blackpool", "description": "Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Blackpool Tower", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb);
