    (v_route, 'Zolder', 'Závodní okruh v Belgii. Motoristický cíl v Belgii — rychlost, okruhy a legendy motorismu na dosah.', 50.98889, 5.25556, 'http://commons.wikimedia.org/wiki/Special:FilePath/Circuit%20Zolder%206-11-2008%2016-29-22.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Circuit%20Zolder%206-11-2008%2016-29-22.jpg"}'::text[], 0, '{"en": {"name": "Circuit Zolder", "description": "Motorsport track in Belgium. A motorsport sight in Belgium — speed, circuits and motoring legends within reach."}, "de": {"name": "Circuit Zolder", "description": "Rennstrecke in Belgien. Ein Motorsport-Ziel in Belgien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Circuit Zolder", "description": "Cel motoryzacyjny w Belgii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Circuit Zolder", "description": "Circuit in België. Een autosportdoel in België — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Zolder", "description": "Circuito de carreras de Bélgica. Un destino del motor en Bélgica: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit de Zolder", "description": "Circuit automobile belge. Un site du sport mécanique en Belgique — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Золдер", "description": "Мотоспортивна пам''ятка у Бельгії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Halen', 'Hrad či zámek v Belgii — historická zastávka, která stojí za odbočku.', 50.94806, 5.11444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sint-Pietersbandenkerk%20%28Halen%29%20%2821764%29%2018-08-2019.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sint-Pietersbandenkerk%20%28Halen%29%20%2821764%29%2018-08-2019.jpg"}'::text[], 1, '{"en": {"name": "Halen", "description": "City in Limburg, Belgium. A castle in Belgium — a historic stop worth the detour."}, "de": {"name": "Halen", "description": "Gemeinde in Belgien. Eine Burg bzw. ein Schloss in Belgien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Halen", "description": "Miasto w Belgii. Zamek w Belgii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Halen", "description": "Gemeente en stad in Limburg, België. Een kasteel in België — een historische stop die de omweg waard is."}, "es": {"name": "Halen", "description": "Municipio de Bélgica. Un castillo en Bélgica: una parada histórica que merece el desvío."}, "fr": {"name": "Halen", "description": "Ville du Limbourg, en Belgique. Un château en Belgique — une halte historique qui vaut le détour."}, "uk": {"name": "Halen", "description": "Замок у Бельгії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Zoutleeuw', 'Sídlo v provincii Vlámský Brabant v Belgii. Hrad či zámek v Belgii — historická zastávka, která stojí za odbočku.', 50.8333, 5.1036, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zoutleeuw%20-%20Casa%20de%20la%20vila.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zoutleeuw%20-%20Casa%20de%20la%20vila.jpg"}'::text[], 2, '{"en": {"name": "Zoutleeuw", "description": "City in Flemish Brabant, Belgium. A castle in Belgium — a historic stop worth the detour."}, "de": {"name": "Zoutleeuw", "description": "Gemeinde in Belgien. Eine Burg bzw. ein Schloss in Belgien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zoutleeuw", "description": "Miasto w Belgii. Zamek w Belgii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Zoutleeuw", "description": "Gemeente en stad in Vlaams-Brabant, België. Een kasteel in België — een historische stop die de omweg waard is."}, "es": {"name": "Zoutleeuw", "description": "Municipio de Bélgica. Un castillo en Bélgica: una parada histórica que merece el desvío."}, "fr": {"name": "Léau", "description": "Ville du Brabant flamand, en Belgique. Un château en Belgique — une halte historique qui vaut le détour."}, "uk": {"name": "Zoutleeuw", "description": "Замок у Бельгії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Basilica of Our Lady', 'Rozhledna v Belgii — výhled do kraje jako odměna za zastávku.', 50.7808, 5.4646, 'http://commons.wikimedia.org/wiki/Special:FilePath/2006.08.17.122359%20Basilika%20Tongeren%20Belgien-2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2006.08.17.122359%20Basilika%20Tongeren%20Belgien-2.jpg"}'::text[], 3, '{"en": {"name": "Basilica of Our Lady", "description": "Church in Tongeren, Belgium. A lookout tower in Belgium — sweeping views as a reward for stopping."}, "de": {"name": "Liebfrauenbasilika (Tongeren)", "description": "Belgische Kirche. Ein Aussichtsturm in Belgien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Basilica of Our Lady", "description": "Wieża widokowa w Belgii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Onze-Lieve-Vrouwebasiliek", "description": "Kerkgebouw in Tongeren, België. Een uitkijktoren in België — weidse uitzichten als beloning voor de stop."}, "es": {"name": "basílica de Nuestra Señora", "description": "Un mirador en Bélgica: amplias vistas como recompensa por la parada."}, "fr": {"name": "basilique Notre-Dame de Tongres", "description": "Édifice religieux belge. Une tour panoramique en Belgique — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Базиліка Тонгеренської Богоматері", "description": "Оглядова вежа у Бельгії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Pevnost Eben-Emael', 'Pevnost v Belgii. Hrad či zámek v Belgii — historická zastávka, která stojí za odbočku.', 50.79722, 5.68083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Fort%20Eben-Emael%20Blok%20I%207-06-2024%2015-07-54.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Fort%20Eben-Emael%20Blok%20I%207-06-2024%2015-07-54.jpg"}'::text[], 4, '{"en": {"name": "Fort Eben-Emael", "description": "Inactive Belgian fortress on the Belgian–Dutch border. A castle in Belgium — a historic stop worth the detour."}, "de": {"name": "Fort Eben-Emael", "description": "Befestigung aus dem zweiten Weltkrieg. Eine Burg bzw. ein Schloss in Belgien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Grupa warowna Eben-Emael", "description": "Zamek w Belgii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Fort Eben-Emael", "description": "Fort in de Tweede Wereldoorlog in België. Een kasteel in België — een historische stop die de omweg waard is."}, "es": {"name": "Fuerte Eben-Emael", "description": "Fortaleza belga inactiva en la frontera entre Alemania y Bélgica. Un castillo en Bélgica: una parada histórica que merece el desvío."}, "fr": {"name": "fort d''Ében-Émael", "description": "Pièce maîtresse de la ceinture fortifiée de Liège. Un château en Belgique — une halte historique qui vaut le détour."}, "uk": {"name": "Форт Ебен Емаель", "description": "Замок у Бельгії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Hoge Kempen National Park', 'Přírodní zajímavost v Belgii — místo na protažení nohou uprostřed přírody.', 51.0, 5.66667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hoge%20Kempen%20034.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hoge%20Kempen%20034.jpg"}'::text[], 5, '{"en": {"name": "Hoge Kempen National Park", "description": "Natura 2000 protected area and national park in Limburg, Belgium. A natural sight in Belgium — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Hoge Kempen", "description": "Nationalpark in Belgien. Eine Natursehenswürdigkeit in Belgien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Hoge Kempen", "description": "Park narodowy w Belgii. Atrakcja przyrodnicza w Belgii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Hoge Kempen", "description": "Natura 2000-gebied en nationaal park in Limburg, België. Een natuurbezienswaardigheid in België — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Hoge Kempen", "description": "Un paraje natural en Bélgica: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de la Haute Campine", "description": "Parc national de la Région Flamande (Belgique). Un site naturel en Belgique — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Хоге Кемпен (національний парк)", "description": "Природна пам''ятка у Бельгії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Wire of Death', 'Hrad či zámek v Belgii — historická zastávka, která stojí za odbočku.', 51.28211, 5.52816, null, '{}'::text[], 6, '{"en": {"name": "Wire of Death", "description": "Electrified border fence in Belgium at the border with the Netherlands. A castle in Belgium — a historic stop worth the detour."}, "de": {"name": "Grenzhochspannungshindernis", "description": "Elektrifizierter Grenzzaun in Belgien an der Grenze zu den Niederlanden. Eine Burg bzw. ein Schloss in Belgien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Granicznej barierę wysokiego napięcia", "description": "Zamek w Belgii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Dodendraad", "description": "Geëlektrificeerd grenshek in België aan grens met Nederland. Een kasteel in België — een historische stop die de omweg waard is."}, "es": {"name": "Alambrada de la Muerte", "description": "Un castillo en Bélgica: una parada histórica que merece el desvío."}, "fr": {"name": "Fil De La Mort", "description": "Clôture frontalière électrifiée en Belgique à la frontière avec les Pays-Bas. Un château en Belgique — une halte historique qui vaut le détour."}, "uk": {"name": "Дріт смерті", "description": "Замок у Бельгії — історична зупинка, варта об''їзду."}}'::jsonb);
