    (v_route, 'Circuit Bremgarten', 'Motoristický cíl ve Švýcarsku — rychlost, okruhy a legendy motorismu na dosah.', 46.95, 7.41083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tennikurvebremgarp.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tennikurvebremgarp.jpg"}'::text[], 0, '{"en": {"name": "Circuit Bremgarten", "description": "Race track. A motorsport sight in Switzerland — speed, circuits and motoring legends within reach."}, "de": {"name": "Bremgarten-Rundstrecke", "description": "Rennstrecke in der Schweiz. Ein Motorsport-Ziel in der Schweiz — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Circuit Bremgarten", "description": "Tor wyścigowy (Szwajcaria). Cel motoryzacyjny w Szwajcarii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Stratencircuit Bremgarten", "description": "Circuit in Zwitserland. Een autosportdoel in Zwitserland — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Circuito de Bremgarten", "description": "Un destino del motor en Suiza: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "Circuit de Bremgarten", "description": "Circuit automobile suisse. Un site du sport mécanique en Suisse — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Траса Бремгартен", "description": "Мотоспортивна пам''ятка у Швейцарії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Zytglogge', 'Hrad či zámek ve Švýcarsku — historická zastávka, která stojí za odbočku.', 46.94806, 7.44778, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zytglogge%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zytglogge%2001.jpg"}'::text[], 1, '{"en": {"name": "Zytglogge", "description": "Medieval clock tower with astronomical clock and carillon in the city of Bern, Switzerland. A castle in Switzerland — a historic stop worth the detour."}, "de": {"name": "Zytglogge", "description": "Mittelalterlicher Uhrturm mit astronomischer Uhr und Glockenspiel in der Berner Altstadt, Schweiz. Eine Burg bzw. ein Schloss in der Schweiz — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zytglogge", "description": "Średniowieczna wieża w Bernie, Szwajcaria. Zamek w Szwajcarii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Zytglogge", "description": "Een kasteel in Zwitserland — een historische stop die de omweg waard is."}, "es": {"name": "Zytgloggeturm", "description": "Un castillo en Suiza: una parada histórica que merece el desvío."}, "fr": {"name": "Zytglogge", "description": "Tour médiévale avec horloge astronomique et carillon dans la ville de Berne, Suisse. Un château en Suisse — une halte historique qui vaut le détour."}, "uk": {"name": "Цитґлоґґе", "description": "Замок у Швейцарії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bielské jezero', 'Vodní plocha ve Švýcarsku — příjemný cíl vyjížďky s výhledy na hladinu.', 47.08556, 7.17417, 'http://commons.wikimedia.org/wiki/Special:FilePath/.00%203431%20Bielersee%20%28Lac%20de%20Bienne%29%20-%20Ort%20Ligerz%2C%20Schweiz.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/.00%203431%20Bielersee%20%28Lac%20de%20Bienne%29%20-%20Ort%20Ligerz%2C%20Schweiz.jpg"}'::text[], 2, '{"en": {"name": "Lake Biel", "description": "Lake at Biel/Bienne, Canton of Bern, Switzerland. A body of water in Switzerland — a pleasant ride destination with waterside views."}, "de": {"name": "Bielersee", "description": "See in der Schweiz. Ein Gewässer in der Schweiz — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Bielersee", "description": "Akwen w Szwajcarii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Biel", "description": "Meer in Zwitserland. Een waterpartij in Zwitserland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Biel/Bienne", "description": "Lago de Suiza. Una masa de agua en Suiza: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Bienne", "description": "Lac suisse. Un plan d''eau en Suisse — une belle destination avec vue sur l''eau."}, "uk": {"name": "Біль", "description": "Озеро на річці Ааре, Швейцарія. Водойма у Швейцарії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Murtenské jezero', 'Jezero ve Švýcarsku. Vodní plocha ve Švýcarsku — příjemný cíl vyjížďky s výhledy na hladinu.', 46.93333, 7.075, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Murten%20%28view%20from%20the%20northeast%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Murten%20%28view%20from%20the%20northeast%29.jpg"}'::text[], 3, '{"en": {"name": "Lake Murten", "description": "Lake in Switzerland. A body of water in Switzerland — a pleasant ride destination with waterside views."}, "de": {"name": "Murtensee", "description": "See in der Schweiz. Ein Gewässer in der Schweiz — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Murtensee", "description": "Akwen w Szwajcarii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Murten", "description": "Meer in Zwitserland. Een waterpartij in Zwitserland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Murten/Morat", "description": "Lago de Suiza. Una masa de agua en Suiza: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Morat", "description": "Lac en Suisse. Un plan d''eau en Suisse — une belle destination avec vue sur l''eau."}, "uk": {"name": "Муртензее", "description": "Водойма у Швейцарії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Neuchâtel Castle', 'Hrad či zámek ve Švýcarsku — historická zastávka, která stojí za odbočku.', 46.99213, 6.92672, 'http://commons.wikimedia.org/wiki/Special:FilePath/Facade%20est%20du%20ch%C3%A2teau%20de%20Neuch%C3%A2tel%20au%20lever%20du%20soleil.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Facade%20est%20du%20ch%C3%A2teau%20de%20Neuch%C3%A2tel%20au%20lever%20du%20soleil.jpg"}'::text[], 4, '{"en": {"name": "Neuchâtel Castle", "description": "Castle on Rue de la Collégiale in the city of Neuchâtel, Switzerland. A castle in Switzerland — a historic stop worth the detour."}, "de": {"name": "Schloss Neuenburg", "description": "Schloss an der Rue de la Collégiale in der Stadt Neuenburg, Schweiz. Eine Burg bzw. ein Schloss in der Schweiz — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Neuchâtel Castle", "description": "Zamek w Szwajcarii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Château de Neuchâtel", "description": "Een kasteel in Zwitserland — een historische stop die de omweg waard is."}, "es": {"name": "castillo de Neuchâtel", "description": "Castillo del cantón de Neuchâtel (Suiza). Un castillo en Suiza: una parada histórica que merece el desvío."}, "fr": {"name": "château de Neuchâtel", "description": "Château du canton de Neuchâtel, en Suisse. Un château en Suisse — une halte historique qui vaut le détour."}, "uk": {"name": "Neuchâtel Castle", "description": "Замок у Швейцарії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála svatého Mikuláše', 'Katedrála ve Fribourgu. Památka ve Švýcarsku — kus historie přímo u trasy.', 46.80611, 7.16306, 'http://commons.wikimedia.org/wiki/Special:FilePath/Fribourg.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Fribourg.jpg"}'::text[], 5, '{"en": {"name": "Fribourg Cathedral", "description": "Cathedral. A heritage sight in Switzerland — a piece of history right on your route."}, "de": {"name": "St. Nikolaus (Freiburg im Üechtland)", "description": "Kirchengebäude in Freiburg/Schweiz. Ein Denkmal in der Schweiz — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Mikołaja we Fryburgu", "description": "Świątynia katolicka. Zabytek w Szwajcarii — kawałek historii tuż przy trasie."}, "nl": {"name": "Fribourg Cathedral", "description": "Kathedraal in Fribourg, Zwitserland. Een monument in Zwitserland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Nicolás", "description": "Friburgo. Un monumento en Suiza: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Nicolas de Fribourg", "description": "Cathédrale suisse. Un monument en Suisse — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Mikuláše", "description": "Пам''ятка у Швейцарії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Thunské jezero', 'Vodní plocha ve Švýcarsku — příjemný cíl vyjížďky s výhledy na hladinu.', 46.68333, 7.71667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Thun%20%28view%20from%20the%20east%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Thun%20%28view%20from%20the%20east%29.jpg"}'::text[], 6, '{"en": {"name": "Lake Thun", "description": "Lake in the canton of Bern, Switzerland. A body of water in Switzerland — a pleasant ride destination with waterside views."}, "de": {"name": "Thunersee", "description": "See im Kanton Bern, Schweiz. Ein Gewässer in der Schweiz — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Thun", "description": "Akwen w Szwajcarii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Thun", "description": "Meer in Zwitserland. Een waterpartij in Zwitserland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Thun", "description": "Lago de Suiza. Una masa de agua en Suiza: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Thoune", "description": "Lac alpin situé dans l''Oberland bernois en Suisse. Un plan d''eau en Suisse — une belle destination avec vue sur l''eau."}, "uk": {"name": "Тунське озеро", "description": "Водойма у Швейцарії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
