  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Porsche Museum', 'Automobilové muzeum v Německu. Motoristický cíl v Německu — rychlost, okruhy a legendy motorismu na dosah.', 48.83446, 9.15195, 'http://commons.wikimedia.org/wiki/Special:FilePath/Porsche%20Museum%20Nacht.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Porsche%20Museum%20Nacht.jpg"}'::text[], 0, '{"en": {"name": "Nunos porsche Museum", "description": "Automobile museum in Germany. A motorsport sight in Germany — speed, circuits and motoring legends within reach."}, "de": {"name": "Porsche-Museum", "description": "Automuseum in Stuttgart. Ein Motorsport-Ziel in Deutschland — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Muzeum Porsche", "description": "Cel motoryzacyjny w Niemczech — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Porsche Museum", "description": "Museum in Baden-Württemberg. Een autosportdoel in Duitsland — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Museo Nuno Porsche", "description": "Un destino del motor en Alemania: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "Porsche Museum", "description": "Musée en Allemagne. Un site du sport mécanique en Allemagne — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Музей Porsche", "description": "Мотоспортивна пам''ятка в Німеччині — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Nový zámek', 'Zámek v německém Stuttgartu. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.7781, 9.18194, 'http://commons.wikimedia.org/wiki/Special:FilePath/StuttgartSchlossPlatz.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/StuttgartSchlossPlatz.JPG"}'::text[], 1, '{"en": {"name": "New Palace", "description": "Palace in Stuttgart. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Neues Schloss", "description": "Schloss in Stuttgart, ehemalige Residenz der Herzöge und Könige von Württemberg. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Nowy Zamek w Stuttgardzie", "description": "Zamek w Niemczech. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Nový zámek", "description": "Kasteel in Stuttgart, Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Nuevo de Stuttgart", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "Nový zámek", "description": "Bâtiment de Stuttgart-Mitte, Stuttgart, Bade-Wurtemberg, Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Nový zámek", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Altes Schloss (Stuttgart, Německo)', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.77696, 9.1797, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Old%20Castle%20Stuttgart%20%28view%20from%20the%20east%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Old%20Castle%20Stuttgart%20%28view%20from%20the%20east%29.jpg"}'::text[], 2, '{"en": {"name": "Old Castle", "description": "Renaissance castle in Stuttgart, Germany, seat of the Landesmuseum Württemberg. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Altes Schloss", "description": "Renaissance Schloss in Stuttgart. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Altes Schloss (Stuttgart, Německo)", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Oude Kasteel", "description": "Stuttgart. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Antiguo de Stuttgart", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "Vieux château de Stuttgart", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Старий замок (Штутгарт)", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Fernsehturm Stuttgart', 'První věž na světě postavená z betonu v roce 1956. Rozhledna v Německu — výhled do kraje jako odměna za zastávku.', 48.75575, 9.19017, 'http://commons.wikimedia.org/wiki/Special:FilePath/Fernsehturm%20Stuttgart%20and%20Full%20Moon%20Summer%202013%2005.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Fernsehturm%20Stuttgart%20and%20Full%20Moon%20Summer%202013%2005.jpg"}'::text[], 3, '{"en": {"name": "Fernsehturm Stuttgart", "description": "TV tower. A lookout tower in Germany — sweeping views as a reward for stopping."}, "de": {"name": "Stuttgarter Fernsehturm", "description": "Fernseh- und Aussichtsturm in Stuttgart. Ein Aussichtsturm in Deutschland — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża telewizyjna w Stuttgarcie", "description": "Wieża widokowa w Niemczech — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Fernsehturm Stuttgart", "description": "Communicatietoren in Stuttgart, Duitsland. Een uitkijktoren in Duitsland — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Fernsehturm de Stuttgart", "description": "Primera torre de televisión del mundo construida de hormigón. Un mirador en Alemania: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour de télévision de Stuttgart", "description": "Tour de télévision allemand, la première tour de télévision de son type dans le monde. Une tour panoramique en Allemagne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Fernsehturm Stuttgart", "description": "Оглядова вежа в Німеччині — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Solitude Palace', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.78694, 9.08417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Solitude%20pan-pjt.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Solitude%20pan-pjt.jpg"}'::text[], 4, '{"en": {"name": "Solitude Palace", "description": "Schloss in Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Solitude", "description": "Schloss in Württemberg. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "pałac Solitude", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Slot Solitude", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio Solitude", "description": "Castillo alemán. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de la Solitude", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Solitude Palace", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bebenhausen Abbey', 'Památka v Německu — kus historie přímo u trasy.', 48.56137, 9.06072, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bebenhausen%20Klosterkirche%20von%20au%C3%9Fen.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bebenhausen%20Klosterkirche%20von%20au%C3%9Fen.jpg"}'::text[], 5, '{"en": {"name": "Bebenhausen Abbey", "description": "Former Cistercian abbey in Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Zisterzienserabtei Bebenhausen", "description": "Ehemaliges Zisterzienserkloster in Baden-Württemberg. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klasztor Bebenhausen", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Bebenhausen", "description": "Klooster in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Bebenhausen Abbey", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Bebenhausen", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bebenhausen Abbey", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Klášter Maulbronn', 'Německý cisterciácký klášter. Památka v Německu — kus historie přímo u trasy.', 49.0011, 8.8129, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Maulbronn%202009.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Maulbronn%202009.jpg"}'::text[], 6, '{"en": {"name": "Maulbronn Monastery", "description": "Monastery in Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Zisterzienserabtei Maulbronn", "description": "Ehemalige Zisterzienserabtei in der Ortsmitte von Maulbronn. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Maulbronn", "description": "Dawny klasztor cystersów w Niemczech. Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Maulbronn", "description": "Klooster in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "monasterio de Maulbronn", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Maulbronn", "description": "Bâtiment de Maulbronn, Karlsruhe, Bade-Wurtemberg, Allemagne. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Маульброннський монастир", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb);
