    (v_route, 'Masarykův okruh', 'Závodní okruh u Brna. Motoristický cíl v Česku — rychlost, okruhy a legendy motorismu na dosah.', 49.20472, 16.45056, 'http://commons.wikimedia.org/wiki/Special:FilePath/Automotodrom%20Brno%20%E2%80%93%20start-finish.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Automotodrom%20Brno%20%E2%80%93%20start-finish.JPG"}'::text[], 0, '{"en": {"name": "Masaryk Circuit", "description": "Race track. A motorsport sight in Czechia — speed, circuits and motoring legends within reach."}, "de": {"name": "Automotodrom Brno", "description": "Ein Motorsport-Ziel in Tschechien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Masaryk Circuit", "description": "Tor wyścigowy (Czechy). Cel motoryzacyjny w Czechach — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Automotodrom Brno", "description": "Circuit in Tsjechië. Een autosportdoel in Tsjechië — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Autódromo de Brno", "description": "Un destino del motor en Chequia: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit de Masaryk", "description": "Circuit routier. Un site du sport mécanique en Tchéquie — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Брно", "description": "Мотоспортивна пам''ятка в Чехії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Veveří', 'Hrad v Brně. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.25667, 16.46167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Veve%C5%99%C3%AD%20-%20panorama.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Veve%C5%99%C3%AD%20-%20panorama.JPG"}'::text[], 1, '{"en": {"name": "Veveří Castle", "description": "Castle in Czechia. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Burg Veveří", "description": "Burg in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Veveří", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Burcht Veveří", "description": "Kasteel in Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Veveří", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Château Veveří", "description": "Château en Tchéquie. Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Veveří", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Starobrněnský klášter', 'Augustiniánský klášter na Starém Brně. Památka v Česku — kus historie přímo u trasy.', 49.19177, 16.59376, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zahrada%20kl%C3%A1%C5%A1tera.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zahrada%20kl%C3%A1%C5%A1tera.JPG"}'::text[], 2, '{"en": {"name": "St Thomas''s Abbey in Brno", "description": "Augustinian monastery in Brno. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Abtei St. Thomas (Alt Brünn)", "description": "Kloster in Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Starobrněnský klášter", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Sint Tomas", "description": "Kerkgebouw in Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Santo Tomás de Brno", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye Saint-Thomas de Brno", "description": "Abbaye tchèque. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Starobrněnský klášter", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'bazilika Nanebevzetí Panny Marie v Brně', 'Kostel v Brně-Starém Brně. Památka v Česku — kus historie přímo u trasy.', 49.19191, 16.59443, 'http://commons.wikimedia.org/wiki/Special:FilePath/%D0%91%D1%80%D0%BD%D0%BE%20%D0%91%D0%B0%D0%B7%D0%B8%D0%BB%D1%96%D0%BA%D0%B0%20%D0%92%D0%BE%D0%B7%D0%BD%D0%B5%D1%81%D1%96%D0%BD%D0%BD%D1%8F%20%D0%94%D1%96%D0%B2%D0%B8%20%D0%9C%D0%B0%D1%80%D1%96%D1%97.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%D0%91%D1%80%D0%BD%D0%BE%20%D0%91%D0%B0%D0%B7%D0%B8%D0%BB%D1%96%D0%BA%D0%B0%20%D0%92%D0%BE%D0%B7%D0%BD%D0%B5%D1%81%D1%96%D0%BD%D0%BD%D1%8F%20%D0%94%D1%96%D0%B2%D0%B8%20%D0%9C%D0%B0%D1%80%D1%96%D1%97.jpg"}'::text[], 3, '{"en": {"name": "Basilica of the Assumption of Our Lady", "description": "Church in Brno-město District of South Moravian region, Czech Republic. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Abteikirche Mariä Himmelfahrt", "description": "Kirche des Thomasklosters in Altbrünn, Brünn, Okres Brno-město, Südmähren, Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Wniebowzięcia Maryi Panny w Brnie", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "bazilika Nanebevzetí Panny Marie v Brně", "description": "Kerkgebouw in Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Basílica de la Asunción de Nuestra Señora", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique de l''Assomption-de-la-Sainte-Vierge-Marie", "description": "Église en République tchèque. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "bazilika Nanebevzetí Panny Marie v Brně", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Špilberk', 'Hrad a pevnost v Brně. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.19444, 16.59889, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20%C5%A0pilberk%20%28Brno%29%2C%20Brno%20-%20st%C5%99ed%20208%2C%20Brno.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20%C5%A0pilberk%20%28Brno%29%2C%20Brno%20-%20st%C5%99ed%20208%2C%20Brno.JPG"}'::text[], 4, '{"en": {"name": "Špilberk Castle", "description": "Building in the Czech Republic, used as prison. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Festung Spielberg", "description": "Burg in Brno, Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Špilberk", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Spielberg", "description": "Burcht. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Špilberk", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse du Spielberg", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Špilberk", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'katedrála svatého Petra a Pavla', 'Katedrála v Brně. Památka v Česku — kus historie přímo u trasy.', 49.19097, 16.60736, 'http://commons.wikimedia.org/wiki/Special:FilePath/Brno%2C%20katedr%C3%A1la%20sv.%20Petra%20a%20Pavla.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Brno%2C%20katedr%C3%A1la%20sv.%20Petra%20a%20Pavla.jpg"}'::text[], 5, '{"en": {"name": "cathedral of St. Peter and Paul", "description": "Cathedral in Brno, Czech Republic. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Kathedrale St. Peter und Paul", "description": "Domkirche des Bistums Brünn in Brünn. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Świętych Apostołów Piotra i Pawła w Brnie", "description": "Świątynia katolicka. Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Petrus-en-Pauluskerk", "description": "Kathedraal in Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Pedro y San Pablo (Brno)", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Pierre-et-Saint-Paul de Brno", "description": "Église tchèque. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "katedrála svatého Petra a Pavla", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Moravský kras', 'Krasová oblast v Česku, geomorfologický podcelek Drahanské vrchoviny. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.27806, 16.73417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Jakubovo%20jezero%20%28Moravsky%20kras%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Jakubovo%20jezero%20%28Moravsky%20kras%29.JPG"}'::text[], 6, '{"en": {"name": "Moravian Karst", "description": "Karst landscape and protected landscape area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Mährischer Karst", "description": "Gebirgszug. Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Kras Morawski", "description": "Jaskinia turystyczna (Powiat Blansko, Czechy). Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Moravische Karst", "description": "Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Karst de Moravia", "description": "Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Karst Morave", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Моравський карст", "description": "Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb);
