    (v_route, 'Mercedes-Benz Museum', 'Motoristický cíl v Německu — rychlost, okruhy a legendy motorismu na dosah.', 48.78855, 9.23376, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mercedes-Benz%20Museum%20201312%2002%20sunset.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mercedes-Benz%20Museum%20201312%2002%20sunset.jpg"}'::text[], 0, '{"en": {"name": "Mercedes-Benz Museum", "description": "Automobile museum in Stuttgart, Germany. A motorsport sight in Germany — speed, circuits and motoring legends within reach."}, "de": {"name": "Mercedes-Benz Museum", "description": "Automobilmuseum in Stuttgart, Deutschland. Ein Motorsport-Ziel in Deutschland — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Mercedes-Benz Welt", "description": "Cel motoryzacyjny w Niemczech — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Mercedes-Benzmuseum", "description": "Museum in Duitsland. Een autosportdoel in Duitsland — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Museo Mercedes-Benz", "description": "Museo de automóviles en Stuttgart, Alemania. Un destino del motor en Alemania: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "musée Mercedes-Benz de Stuttgart", "description": "Musée en Allemagne. Un site du sport mécanique en Allemagne — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Музей Мерседес-Бенц", "description": "Музей у Штутгарті (Німеччина). Мотоспортивна пам''ятка в Німеччині — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Max-Eyth-See', 'Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 48.83524, 9.21624, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stuttgart%20Max-Eyth-See.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stuttgart%20Max-Eyth-See.JPG"}'::text[], 1, '{"en": {"name": "Max-Eyth-See", "description": "Lake in Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Max-Eyth-See", "description": "See in Deutschland. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Max-Eyth-See", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Max-Eyth-See", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Max-Eyth", "description": "Lago de Alemania. Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Max-Eyth-See", "description": "Lac allemand. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Max-Eyth-See", "description": "Озеро в Німеччині. Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
