    (v_route, 'Klášter Hirsau', 'Památka v Německu — kus historie přímo u trasy.', 48.7378, 8.7321, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Hirsau%202010.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Hirsau%202010.jpg"}'::text[], 4, '{"en": {"name": "Hirsau Abbey", "description": "Former Benedictine abbey in Calw. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Benediktinerabtei Hirsau", "description": "Ehemaliges Benediktinerkloster in Hirsau bei Calw. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klasztor Hirsau", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Klášter Hirsau", "description": "Abdij in Baden-Württemberg, Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Klášter Hirsau", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Hirsau", "description": "Ancienne abbaye bénédictine de Calw. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Klášter Hirsau", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
