    (v_route, 'lac Pavin', 'Sopečné jezero ve Francii. Vodní plocha ve Francii — příjemný cíl vyjížďky s výhledy na hladinu.', 45.49585, 2.88792, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Pavin%20Vue%20g%C3%A9n%C3%A9.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Pavin%20Vue%20g%C3%A9n%C3%A9.JPG"}'::text[], 5, '{"en": {"name": "Lac Pavin", "description": "Body of water. A body of water in France — a pleasant ride destination with waterside views."}, "de": {"name": "Lac Pavin", "description": "Ein Gewässer in Frankreich — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "lac Pavin", "description": "Akwen we Francji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Lac Pavin", "description": "Een waterpartij in Frankrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "lac Pavin", "description": "Una masa de agua en Francia: un destino agradable con vistas al agua."}, "fr": {"name": "lac Pavin", "description": "Lac français. Un plan d''eau en France — une belle destination avec vue sur l''eau."}, "uk": {"name": "lac Pavin", "description": "Водний об''єкт. Водойма у Франції — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
