    (v_route, 'MotorLand Aragón', 'Motoristický cíl ve Španělsku — rychlost, okruhy a legendy motorismu na dosah.', 41.07968, -0.18724, 'http://commons.wikimedia.org/wiki/Special:FilePath/Marc%20M%C3%A1rquez%20leads%20the%20pack%202014%20Arag%C3%B3n.jpeg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Marc%20M%C3%A1rquez%20leads%20the%20pack%202014%20Arag%C3%B3n.jpeg"}'::text[], 0, '{"en": {"name": "MotorLand Aragón", "description": "Race track. A motorsport sight in Spain — speed, circuits and motoring legends within reach."}, "de": {"name": "Motorland Aragón", "description": "Ein Motorsport-Ziel in Spanien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Ciudad del Motor de Aragón", "description": "Tor wyścigowy w Hiszpanii. Cel motoryzacyjny w Hiszpanii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Motorland Aragón", "description": "Circuit in Spanje. Een autosportdoel in Spanje — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Ciudad del Motor de Aragón", "description": "Autódromo español. Un destino del motor en España: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "Circuit Motorland Aragon", "description": "Un site du sport mécanique en Espagne — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Моторленд Арагон", "description": "Мотоспортивна пам''ятка в Іспанії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Castle of the Calatravos', 'Hrad či zámek ve Španělsku — historická zastávka, která stojí za odbočku.', 41.04831, -0.13265, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Alca%C3%B1iz%2C%20Teruel%20%28Spain%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Alca%C3%B1iz%2C%20Teruel%20%28Spain%29.JPG"}'::text[], 1, '{"en": {"name": "Castle of the Calatravos", "description": "Cultural property in Alcañiz, Spain. A castle in Spain — a historic stop worth the detour."}, "de": {"name": "Castillo de Alcañiz", "description": "Burg in Spanien. Eine Burg bzw. ein Schloss in Spanien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Castle of the Calatravos", "description": "Zamek w Hiszpanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castle of the Calatravos", "description": "Kasteel in Alcañiz, Spanje. Een kasteel in Spanje — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de los Calatravos", "description": "Construcción defensiva-residencial en Alcañiz, Bajo Aragón, Teruel, España. Un castillo en España: una parada histórica que merece el desvío."}, "fr": {"name": "château d''Alcañiz", "description": "Château fort espagnol. Un château en Espagne — une halte historique qui vaut le détour."}, "uk": {"name": "Castle of the Calatravos", "description": "Пам''ятка культурної спадщини в Іспанії. Замок в Іспанії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Castle of Maella', 'Hrad či zámek ve Španělsku — historická zastávka, která stojí za odbočku.', 41.12194, 0.14167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castell%20del%20Comte%20d%27Aranda.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castell%20del%20Comte%20d%27Aranda.jpg"}'::text[], 2, '{"en": {"name": "Castle of Maella", "description": "A castle in Spain — a historic stop worth the detour."}, "de": {"name": "Castle of Maella", "description": "Burg in Spanien. Eine Burg bzw. ein Schloss in Spanien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Castle of Maella", "description": "Zamek w Hiszpanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castle of Maella", "description": "Een kasteel in Spanje — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Maella", "description": "Edificio en Maella, provincia de Zaragoza, Aragón, España. Un castillo en España: una parada histórica que merece el desvío."}, "fr": {"name": "Castle of Maella", "description": "Château fort espagnol. Un château en Espagne — une halte historique qui vaut le détour."}, "uk": {"name": "Castle of Maella", "description": "Замок в Іспанії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Trapa de Santa Susana', 'Památka ve Španělsku — kus historie přímo u trasy.', 41.16222, 0.13083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Maella%20-%20Priorato%20Santa%20Susana%20-%20Vista%20general.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Maella%20-%20Priorato%20Santa%20Susana%20-%20Vista%20general.jpg"}'::text[], 3, '{"en": {"name": "Trapa de Santa Susana", "description": "Former monastery in Maella, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Kloster Trapa von Santa Susana", "description": "Kloster in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Trapa de Santa Susana", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Trapa de Santa Susana", "description": "Klooster in Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio de Santa María de la Trapa de Santa Susana", "description": "Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "Trapa de Santa Susana", "description": "Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Trapa de Santa Susana", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Roca dels Moros', 'Rozcestník na projektech Wikimedia. Přírodní zajímavost ve Španělsku — místo na protažení nohou uprostřed přírody.', 40.95556, 0.18389, 'http://commons.wikimedia.org/wiki/Special:FilePath/Pintures%20de%20la%20Cova%20dels%20Moros%20-%20Museu%20d%27Arqueologia%20de%20Catalunya%20%28Barcelona%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Pintures%20de%20la%20Cova%20dels%20Moros%20-%20Museu%20d%27Arqueologia%20de%20Catalunya%20%28Barcelona%29.JPG"}'::text[], 4, '{"en": {"name": "Roca dels Moros", "description": "Cultural property in Cretas, Spain. A natural sight in Spain — a spot to stretch your legs amid nature."}, "de": {"name": "Roca dels Moros", "description": "Archäologische Stätte in Spanien. Eine Natursehenswürdigkeit in Spanien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Roca dels Moros", "description": "Strona ujednoznaczniająca w projekcie Wikimedia. Atrakcja przyrodnicza w Hiszpanii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Roca dels Moros", "description": "Archeologische vindplaats in Spanje. Een natuurbezienswaardigheid in Spanje — een plek om de benen te strekken in de natuur."}, "es": {"name": "Roca de los Moros", "description": "Bien de interés cultural. Un paraje natural en España: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Roca dels Moros", "description": "Grotte en Espagne. Un site naturel en Espagne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Roca dels Moros", "description": "Сторінка значень у проєкті Вікімедіа. Природна пам''ятка в Іспанії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Castellote Castle', 'Hrad či zámek ve Španělsku — historická zastávka, která stojí za odbočku.', 40.80149, -0.32205, 'http://commons.wikimedia.org/wiki/Special:FilePath/Conjunto%20de%20Castellote.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Conjunto%20de%20Castellote.JPG"}'::text[], 5, '{"en": {"name": "Castellote Castle", "description": "A castle in Spain — a historic stop worth the detour."}, "de": {"name": "Castellote Castle", "description": "Burg in Spanien. Eine Burg bzw. ein Schloss in Spanien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Castellote Castle", "description": "Zamek w Hiszpanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castellote Castle", "description": "Kasteel. Een kasteel in Spanje — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Castellote", "description": "Fortaleza en la provincia española de Teruel. Un castillo en España: una parada histórica que merece el desvío."}, "fr": {"name": "château de Castellote", "description": "Un château en Espagne — une halte historique qui vaut le détour."}, "uk": {"name": "Castellote Castle", "description": "Замок в Іспанії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Klášter Rueda', 'Památka ve Španělsku — kus historie přímo u trasy.', 41.29694, -0.31361, 'http://commons.wikimedia.org/wiki/Special:FilePath/Monasterio%20de%20Nuestra%20Se%C3%B1ora%20de%20Rueda%2C%20S%C3%A1stago%2C%20Zaragoza%2C%20Espa%C3%B1a%2C%202015-12-23%2C%20DD%2029.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Monasterio%20de%20Nuestra%20Se%C3%B1ora%20de%20Rueda%2C%20S%C3%A1stago%2C%20Zaragoza%2C%20Espa%C3%B1a%2C%202015-12-23%2C%20DD%2029.JPG"}'::text[], 6, '{"en": {"name": "Rueda Abbey", "description": "Monastery. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Kloster Rueda", "description": "Kloster in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klášter Rueda", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Rueda Abbey", "description": "Klooster in Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio de Nuestra Señora de Rueda", "description": "Bien de Interés Cultural en el municipio de Sástago, España. Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "Klášter Rueda", "description": "Monument historique d''Espagne. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Klášter Rueda", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb);
