    (v_route, 'TT Circuit Assen', 'Motoristický cíl v Nizozemsku — rychlost, okruhy a legendy motorismu na dosah.', 52.96156, 6.5233, 'http://commons.wikimedia.org/wiki/Special:FilePath/Moto3%20riders%20racing%20at%202025%20Dutch%20TT.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Moto3%20riders%20racing%20at%202025%20Dutch%20TT.jpg"}'::text[], 0, '{"en": {"name": "TT Circuit Assen", "description": "Motorsport track in the Netherlands. A motorsport sight in the Netherlands — speed, circuits and motoring legends within reach."}, "de": {"name": "TT Circuit Assen", "description": "Motorsport-Rennstrecke bei der niederländischen Stadt Assen. Ein Motorsport-Ziel in den Niederlanden — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "TT Circuit Assen", "description": "Cel motoryzacyjny w Holandii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "TT-Circuit Assen", "description": "Circuit in Assen. Een autosportdoel in Nederland — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Circuito de Assen", "description": "Circuito de carreras de Países Bajos. Un destino del motor en los Países Bajos: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "TT Circuit Assen", "description": "Un site du sport mécanique aux Pays-Bas — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Ассен", "description": "Мотоспортивна пам''ятка в Нідерландах — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Drentsche Aa National Park', 'Přírodní zajímavost v Nizozemsku — místo na protažení nohou uprostřed přírody.', 53.04161, 6.64945, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kymmelsberg%20Schipborg.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kymmelsberg%20Schipborg.jpg"}'::text[], 1, '{"en": {"name": "Drentsche Aa National Park", "description": "National park in the Netherlands. A natural sight in the Netherlands — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Drentsche Aa", "description": "Nationalpark im Nordosten der Niederlande. Eine Natursehenswürdigkeit in den Niederlanden — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Drentsche Aa National Park", "description": "Atrakcja przyrodnicza w Holandii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Drentsche Aa", "description": "Nationaal park in Nederland. Een natuurbezienswaardigheid in Nederland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Nationaal beek- en esdorpenlandschap Drentsche Aa", "description": "Área protegida de Reino de los Países Bajos (NP-5). Un paraje natural en los Países Bajos: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national Drentsche Aa", "description": "Parc national néerlandais. Un site naturel aux Pays-Bas — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Дрентше Аа (національний парк)", "description": "Природна пам''ятка в Нідерландах — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Zuidlaardermeer', 'Vodní plocha v Nizozemsku — příjemný cíl vyjížďky s výhledy na hladinu.', 53.12056, 6.69556, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zuidlaardermeer2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zuidlaardermeer2.jpg"}'::text[], 2, '{"en": {"name": "Zuidlaardermeer", "description": "Lake in the Netherlands. A body of water in the Netherlands — a pleasant ride destination with waterside views."}, "de": {"name": "Zuidlaardermeer", "description": "See in den Niederlanden. Ein Gewässer in den Niederlanden — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zuidlaardermeer", "description": "Akwen w Holandii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Zuidlaardermeer", "description": "Meer in Nederland. Een waterpartij in Nederland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Zuidlaardermeer", "description": "Lago en Países Bajos. Una masa de agua en los Países Bajos: un destino agradable con vistas al agua."}, "fr": {"name": "Zuidlaardermeer", "description": "Lac néerlandais. Un plan d''eau aux Pays-Bas — une belle destination avec vue sur l''eau."}, "uk": {"name": "Zuidlaardermeer", "description": "Водойма в Нідерландах — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'St. Joseph Cathedral, Groningen', 'Památka v Nizozemsku — kus historie přímo u trasy.', 53.21472, 6.57278, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sint-Jozefkathedraal2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sint-Jozefkathedraal2.jpg"}'::text[], 3, '{"en": {"name": "St. Joseph Cathedral, Groningen", "description": "Church in Groningen, Netherlands. A heritage sight in the Netherlands — a piece of history right on your route."}, "de": {"name": "St.-Josef-Kathedrale", "description": "Kirchengebäude in der Niederlande. Ein Denkmal in den Niederlanden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Józefa w Groningen", "description": "Świątynia katolicka. Zabytek w Holandii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Jozefkerk", "description": "Groningen. Een monument in Nederland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San José", "description": "Catedral católica en Groninga, Países Bajos. Un monumento en los Países Bajos: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Joseph de Groningue", "description": "Église néerlandaise. Un monument aux Pays-Bas — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор святого Йозефа", "description": "Пам''ятка в Нідерландах — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Groningen', 'Sídlo v provincii Groningen v Nizozemsku. Hrad či zámek v Nizozemsku — historická zastávka, která stojí za odbočku.', 53.21889, 6.5675, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hoge%20der%20Aa2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hoge%20der%20Aa2.jpg"}'::text[], 4, '{"en": {"name": "Groningen", "description": "Capital city of the province of Groningen, the Netherlands. A castle in the Netherlands — a historic stop worth the detour."}, "de": {"name": "Groningen", "description": "Hauptstadt der Provinz Groningen in den Niederlanden. Eine Burg bzw. ein Schloss in den Niederlanden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Groningen", "description": "Miasto w Holandii. Zamek w Holandii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Groningen", "description": "Hoofdstad van de Nederlandse provincie Groningen. Een kasteel in Nederland — een historische stop die de omweg waard is."}, "es": {"name": "Groninga", "description": "Capital de la provincia de Groninga (Países Bajos). Un castillo en los Países Bajos: una parada histórica que merece el desvío."}, "fr": {"name": "Groningue", "description": "Chef-lieu de la province de Groningue aux Pays-Bas. Un château aux Pays-Bas — une halte historique qui vaut le détour."}, "uk": {"name": "Гронінген", "description": "Місто на півночі Нідерландів, адміністративний центр провінції Гронінген. Замок в Нідерландах — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Drents-Friese Wold National Park', 'Přírodní zajímavost v Nizozemsku — místo na protažení nohou uprostřed přírody.', 52.90972, 6.28056, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aekingerzand%20Nationaal%20Park%20Drents-Friese%20Wold4.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aekingerzand%20Nationaal%20Park%20Drents-Friese%20Wold4.jpg"}'::text[], 5, '{"en": {"name": "Drents-Friese Wold National Park", "description": "National park in the Netherlands. A natural sight in the Netherlands — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Drents-Friese Wold", "description": "Nationalpark im Norden der Niederlande. Eine Natursehenswürdigkeit in den Niederlanden — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Drents-Friese Wold", "description": "Atrakcja przyrodnicza w Holandii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Drents-Friese Wold", "description": "Nationaal park in Nederland. Een natuurbezienswaardigheid in Nederland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Drents-Friese Wold", "description": "Área protegida de Reino de los Países Bajos (NP-4). Un paraje natural en los Países Bajos: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national Drents-Friese Wold", "description": "Parc naturel néerlandais. Un site naturel aux Pays-Bas — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Дрентс-Фріз Волд (національний парк)", "description": "Природна пам''ятка в Нідерландах — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Dwingelderveld National Park', 'Přírodní zajímavost v Nizozemsku — místo na protažení nohou uprostřed přírody.', 52.81639, 6.4075, 'http://commons.wikimedia.org/wiki/Special:FilePath/Heide%20op%20het%20Dwingelderveld.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Heide%20op%20het%20Dwingelderveld.JPG"}'::text[], 6, '{"en": {"name": "Dwingelderveld National Park", "description": "National park in Drenthe, the Netherlands. A natural sight in the Netherlands — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Dwingelderveld", "description": "Nationalpark im Nordwesten der Niederlande. Eine Natursehenswürdigkeit in den Niederlanden — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Dwingelderveld National Park", "description": "Atrakcja przyrodnicza w Holandii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Dwingelderveld", "description": "Nationaal park in Drenthe, Nederland. Een natuurbezienswaardigheid in Nederland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Dwingelderveld", "description": "Área protegida de Reino de los Países Bajos. Un paraje natural en los Países Bajos: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national Dwingelderveld", "description": "Un site naturel aux Pays-Bas — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Двінгельдервельд (національний парк)", "description": "Природна пам''ятка в Нідерландах — місце розім''яти ноги серед природи."}}'::jsonb);
