    (v_route, 'Fiorano Circuit', 'Motoristický cíl v Itálii — rychlost, okruhy a legendy motorismu na dosah.', 44.53418, 10.85728, 'http://commons.wikimedia.org/wiki/Special:FilePath/%E3%83%95%E3%82%A3%E3%82%AA%E3%83%A9%E3%83%8E%E3%82%B5%E3%83%BC%E3%82%AD%E3%83%83%E3%83%88%20%2836331712583%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%E3%83%95%E3%82%A3%E3%82%AA%E3%83%A9%E3%83%8E%E3%82%B5%E3%83%BC%E3%82%AD%E3%83%83%E3%83%88%20%2836331712583%29.jpg"}'::text[], 0, '{"en": {"name": "Fiorano Circuit", "description": "Race track. A motorsport sight in Italy — speed, circuits and motoring legends within reach."}, "de": {"name": "Pista di Fiorano", "description": "Rennstrecke in Italien. Ein Motorsport-Ziel in Italien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Tor Fiorano", "description": "Tor wyścigowy (Włochy). Cel motoryzacyjny we Włoszech — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Pista di Fiorano", "description": "Circuit in Italië. Een autosportdoel in Italië — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Circuito de Fiorano", "description": "Un destino del motor en Italia: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit de Fiorano", "description": "Un site du sport mécanique en Italie — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Фьорано", "description": "Мотоспортивна пам''ятка в Італії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
