    (v_route, 'Jarama Circuit', 'Motoristický cíl ve Španělsku — rychlost, okruhy a legendy motorismu na dosah.', 40.61711, -3.58558, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tribuna%20recta%20Circuito%20del%20Jarama.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tribuna%20recta%20Circuito%20del%20Jarama.jpg"}'::text[], 0, '{"en": {"name": "Jarama Circuit", "description": "Motorsport venue in Madrid, Spain. A motorsport sight in Spain — speed, circuits and motoring legends within reach."}, "de": {"name": "Circuito del Jarama", "description": "Rennstrecke in Spanien. Ein Motorsport-Ziel in Spanien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Circuito del Jarama", "description": "Tor wyścigowy (Hiszpania). Cel motoryzacyjny w Hiszpanii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Circuito Permanente del Jarama", "description": "Circuit in Spanje. Een autosportdoel in Spanje — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Circuito del Jarama", "description": "Autódromo español. Un destino del motor en España: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "Circuit permanent du Jarama", "description": "Circuit automobile espagnol. Un site du sport mécanique en Espagne — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Харама (траса)", "description": "Мотоспортивна пам''ятка в Іспанії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Alcalá Gate', 'Hrad či zámek ve Španělsku — historická zastávka, která stojí za odbočku.', 40.42002, -3.68873, 'http://commons.wikimedia.org/wiki/Special:FilePath/Puerta%20de%20Alcal%C3%A1%202025.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Puerta%20de%20Alcal%C3%A1%202025.jpg"}'::text[], 1, '{"en": {"name": "Alcalá Gate", "description": "Cultural property in Madrid Distritos: Retiro y Salamanca, Spain. A castle in Spain — a historic stop worth the detour."}, "de": {"name": "Puerta de Alcalá", "description": "Denkmal in Spanien. Eine Burg bzw. ein Schloss in Spanien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Puerta de Alcalá", "description": "Klasycystyczny pomnik. Zamek w Hiszpanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Puerta de Alcalá", "description": "Triomfboog in Madrid, Spanje. Een kasteel in Spanje — een historische stop die de omweg waard is."}, "es": {"name": "Puerta de Alcalá", "description": "Antigua puerta de entrada/salida de Madrid. Un castillo en España: una parada histórica que merece el desvío."}, "fr": {"name": "porte de Alcalá", "description": "Monument à Madrid. Un château en Espagne — une halte historique qui vaut le détour."}, "uk": {"name": "Alcalá Gate", "description": "Пам''ятка культурної спадщини в Іспанії. Замок в Іспанії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Klášter koletinských klarisek v Madridu', 'Klášter v Madridu. Památka ve Španělsku — kus historie přímo u trasy.', 40.41827, -3.70619, 'http://commons.wikimedia.org/wiki/Special:FilePath/Monasterio%20de%20las%20Descalzas%20Reales%20%28Madrid%29%2007.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Monasterio%20de%20las%20Descalzas%20Reales%20%28Madrid%29%2007.jpg"}'::text[], 2, '{"en": {"name": "Convent of Las Descalzas Reales", "description": "Monastery in Madrid, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Monasterio de las Descalzas Reales", "description": "Denkmal in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Descalzas Reales", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Monasterio de las Descalzas Reales", "description": "Klooster en museum in Madrid. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio de las Descalzas Reales", "description": "Monasterio de la ciudad de Madrid, (España). Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère des Déchaussées royales", "description": "Monument historique d''Espagne. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Дескальсас-Реалес", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála Panny Marie Almudenské v Madridu', 'Katedrála ve Španělsku. Památka ve Španělsku — kus historie přímo u trasy.', 40.41556, -3.71444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Almudena%202022%20-%20overview.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Almudena%202022%20-%20overview.jpg"}'::text[], 3, '{"en": {"name": "Almudena Cathedral", "description": "Roman Catholic cathedral in Madrid, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Almudena-Kathedrale", "description": "Gebäude in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Catedral de la Almudena", "description": "Świątynia katolicka. Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Madrid", "description": "Bouwwerk in Madrid. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "catedral de la Almudena", "description": "Catedral de Madrid (España). Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l''Almudena", "description": "Cathédrale catholique romaine à Madrid, Espagne. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор де ла Альмудена", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Gate of Toledo', 'Hrad či zámek ve Španělsku — historická zastávka, která stojí za odbočku.', 40.40671, -3.71162, 'http://commons.wikimedia.org/wiki/Special:FilePath/Puerta%20de%20Toledo.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Puerta%20de%20Toledo.jpg"}'::text[], 4, '{"en": {"name": "Gate of Toledo", "description": "Cultural property in Madrid Distritos: Centro y Arganzuela, Spain. A castle in Spain — a historic stop worth the detour."}, "de": {"name": "Puerta de Toledo", "description": "Denkmal in Spanien. Eine Burg bzw. ein Schloss in Spanien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Gate of Toledo", "description": "Zamek w Hiszpanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Gate of Toledo", "description": "Een kasteel in Spanje — een historische stop die de omweg waard is."}, "es": {"name": "Puerta de Toledo", "description": "Puerta monumental de Madrid. Un castillo en España: una parada histórica que merece el desvío."}, "fr": {"name": "porte de Tolède", "description": "Monument de Madrid, Espagne. Un château en Espagne — une halte historique qui vaut le détour."}, "uk": {"name": "Gate of Toledo", "description": "Пам''ятка культурної спадщини в Іспанії. Замок в Іспанії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Cathedral of los Santos Niños Justo y Pastor de Alcalá de Henares', 'Památka ve Španělsku — kus historie přímo u trasy.', 40.48053, -3.36926, 'http://commons.wikimedia.org/wiki/Special:FilePath/Alcala%20cathedral%202023%20-%20western%20fa%C3%A7ade.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Alcala%20cathedral%202023%20-%20western%20fa%C3%A7ade.jpg"}'::text[], 5, '{"en": {"name": "Cathedral of los Santos Niños Justo y Pastor de Alcalá de Henares", "description": "Cultural property in Alcalá de Henares, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Kathedrale von Alcalá de Henares", "description": "Kirchengebäude in Alcalá de Henares, Autonome Gemeinschaft Madrid, Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Cathedral of los Santos Niños Justo y Pastor de Alcalá de Henares", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Cathedral of los Santos Niños Justo y Pastor de Alcalá de Henares", "description": "Kathedraal in Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de los Santos Niños Justo y Pastor de Alcalá de Henares", "description": "Edificio de Alcalá de Henares, (España). Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale d''Alcalá de Henares", "description": "Monument historique d''Espagne. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святих дітей", "description": "Пам''ятка культурної спадщини в Іспанії. Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Guadarrama National Park', 'Přírodní zajímavost ve Španělsku — místo na protažení nohou uprostřed přírody.', 40.78333, -3.98333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Circo%20y%20cima%20de%20Pe%C3%B1alara1.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Circo%20y%20cima%20de%20Pe%C3%B1alara1.JPG"}'::text[], 6, '{"en": {"name": "Guadarrama National Park", "description": "National park in Spain. A natural sight in Spain — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Sierra de Guadarrama", "description": "Nationalpark in Spanien. Eine Natursehenswürdigkeit in Spanien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Guadarrama National Park", "description": "Atrakcja przyrodnicza w Hiszpanii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal park Sierra de Guadarrama", "description": "Natuurgebied in Spanje. Een natuurbezienswaardigheid in Spanje — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de la Sierra de Guadarrama", "description": "Área protegida de las provincias españolas de Madrid y Segovia. Un paraje natural en España: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de la Sierra de Guadarrama", "description": "Parc national de l''Espagne. Un site naturel en Espagne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Національний парк Сьєрра-де-Гвадаррама", "description": "Природна пам''ятка в Іспанії — місце розім''яти ноги серед природи."}}'::jsonb);
