    (v_route, 'Brooklands', 'Závodní okruh. Motoristický cíl ve Velké Británii — rychlost, okruhy a legendy motorismu na dosah.', 51.34889, -0.4725, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rally%20car%20on%20Members%27%20Banking.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rally%20car%20on%20Members%27%20Banking.jpg"}'::text[], 0, '{"en": {"name": "Brooklands", "description": "Race track. A motorsport sight in the United Kingdom — speed, circuits and motoring legends within reach."}, "de": {"name": "Brooklands", "description": "Britische Rennstrecke. Ein Motorsport-Ziel in Großbritannien — Geschwindigkeit, Rennstrecken und Legenden zum Anfassen."}, "pl": {"name": "Brooklands", "description": "Tor wyścigowy (Wielka Brytania). Cel motoryzacyjny w Wielkiej Brytanii — prędkość, tory i legendy motoryzacji na wyciągnięcie ręki."}, "nl": {"name": "Brooklands", "description": "Circuit. Een autosportdoel in het Verenigd Koninkrijk — snelheid, circuits en motorlegendes binnen handbereik."}, "es": {"name": "Brooklands", "description": "Un destino del motor en el Reino Unido: velocidad, circuitos y leyendas del motor al alcance."}, "fr": {"name": "circuit de Brooklands", "description": "Circuit automobile, près de Londres, Royaume-Uni. Un site du sport mécanique au Royaume-Uni — vitesse, circuits et légendes de la moto à portée de main."}, "uk": {"name": "Brooklands", "description": "Мотоспортивна пам''ятка у Великій Британії — швидкість, треки й легенди автоспорту поруч."}}'::jsonb),
    (v_route, 'Richmond Park', 'Park v Londýně. Přírodní zajímavost ve Velké Británii — místo na protažení nohou uprostřed přírody.', 51.44333, -0.275, 'http://commons.wikimedia.org/wiki/Special:FilePath/Isabella%20Plantation%2C%20Richmond%20Park%2C%20London%20-%20April%202011.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Isabella%20Plantation%2C%20Richmond%20Park%2C%20London%20-%20April%202011.jpg"}'::text[], 1, '{"en": {"name": "Richmond Park", "description": "Royal Park in London, England, UK. A natural sight in the United Kingdom — a spot to stretch your legs amid nature."}, "de": {"name": "Richmond Park", "description": "Park im Vereinigten Königreich. Eine Natursehenswürdigkeit in Großbritannien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Richmond Park", "description": "Atrakcja przyrodnicza w Wielkiej Brytanii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Richmond Park", "description": "Park in het Verenigd Koninkrijk. Een natuurbezienswaardigheid in het Verenigd Koninkrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque Richmond", "description": "Parque situado en Londres, Reino Unido. Un paraje natural en el Reino Unido: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Richmond Park", "description": "Le plus grand parc de Londres, district de Richmond upon Thames. Un site naturel au Royaume-Uni — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Річмонд-парк", "description": "Природна пам''ятка у Великій Британії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Serpentine', 'Vodní plocha ve Velké Británii — příjemný cíl vyjížďky s výhledy na hladinu.', 51.50528, -0.16944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Serpentine%20Lake.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Serpentine%20Lake.jpg"}'::text[], 2, '{"en": {"name": "Serpentine", "description": "Lake in Hyde Park, London, United Kingdom. A body of water in the United Kingdom — a pleasant ride destination with waterside views."}, "de": {"name": "The Serpentine", "description": "See in Hyde Park, London. Ein Gewässer in Großbritannien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Serpentine", "description": "Jezioro w Hyde Parku w Londynie. Akwen w Wielkiej Brytanii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Serpentine", "description": "Meer in Hyde Park, Londen. Een waterpartij in het Verenigd Koninkrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Serpentine", "description": "Lago en Hyde Park, Londres. Una masa de agua en el Reino Unido: un destino agradable con vistas al agua."}, "fr": {"name": "Serpentine", "description": "Lac dans Hyde Park à Londres. Un plan d''eau au Royaume-Uni — une belle destination avec vue sur l''eau."}, "uk": {"name": "Серпентин", "description": "Водойма у Великій Британії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Věž British Telecom', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.5215, -0.1389, 'http://commons.wikimedia.org/wiki/Special:FilePath/BT%20Tower-1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/BT%20Tower-1.jpg"}'::text[], 3, '{"en": {"name": "BT Tower", "description": "Communications tower located in Fitzrovia, London, England, UK. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "BT Tower", "description": "Londoner Fernsehturm. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "BT Tower", "description": "Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "BT Tower", "description": "Communicatietoren in Camden, Verenigd Koninkrijk. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre BT", "description": "Torre de telecomunicaciones en Reino Unido. Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "BT Tower", "description": "Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Věž British Telecom", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Katedrála v Southwarku', 'Katedrála v Anglii. Památka ve Velké Británii — kus historie přímo u trasy.', 51.50611, -0.08972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Northwest%20View%20of%20Southwark%20Cathedral%20%2801%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Northwest%20View%20of%20Southwark%20Cathedral%20%2801%29.jpg"}'::text[], 4, '{"en": {"name": "Southwark Cathedral", "description": "Mother church of the Anglican Diocese of Southwark. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Southwark Cathedral", "description": "Kirchengebäude in London. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Southwark", "description": "Kościół anglikański w Londynie. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Southwark", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Southwark", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Southwark", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála v Southwarku", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'ArcelorMittal Orbit', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.53833, -0.01333, 'http://commons.wikimedia.org/wiki/Special:FilePath/ArcelorMittal%20Orbit%20at%20night.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/ArcelorMittal%20Orbit%20at%20night.jpg"}'::text[], 5, '{"en": {"name": "ArcelorMittal Orbit", "description": "Sculpture and observation tower in the Olympic Park in Stratford, London. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "ArcelorMittal Orbit", "description": "Skulptur von Anish Kapoor und Cecil Balmond im Olympic Park in Stratford, London. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "ArcelorMittal Orbit", "description": "Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "ArcelorMittal Orbit", "description": "Bouwwerk in Londen. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "ArcelorMittal Orbit", "description": "Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour Orbit", "description": "Œuvre de Anish Kapoor et Cecil Balmond. Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "ArcelorMittal Orbit", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Zámek Windsor', 'Anglický hrad. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.48389, -0.60444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Windsor%20Castle%20at%20Sunset%20-%20Nov%202006.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Windsor%20Castle%20at%20Sunset%20-%20Nov%202006.jpg"}'::text[], 6, '{"en": {"name": "Windsor Castle", "description": "Royal residence at Windsor in Berkshire, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Windsor Castle", "description": "Schloss in England im Besitz der britischen Krone. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Windsor", "description": "Rezydencja królów angielskich od 1110 roku, położona w mieście Windsor. Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Windsor Castle", "description": "Kasteel in Berkshire, Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Windsor", "description": "Palacio y residencia de la monarca del Reino Unido y de la Mancomunidad de Naciones. Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Windsor", "description": "Château britannique en Angleterre. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Віндзорський замок", "description": "Королівський палац в Англії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb);
